Object.assign(window.TEM8_DICTIONARY, {"angled":{"oxford":{"phon":"ˈæŋɡl","pos":"noun","senses":[{"en":"the space between two lines or surfaces that join, measured in degrees","cn":"角"},{"en":"the direction that sth is leaning or pointing in when it is not in a vertical or horizontal line","cn":"斜角；角度"}]}},"ans":{"media":{"uk":"media/uk/an__gb_1.mp3","us":"media/us/an__us_1.mp3"}},"announcements":{"oxford":{"phon":"əˈnaʊnsmənt","pos":"noun","senses":[{"en":"a spoken or written statement that informs people about sth （","cn":"一项）公告，布告，通告"},{"en":"the act of publicly informing people about sth （","cn":"指行动）宣布，宣告"}]},"media":{"uk":"media/uk/announcement__gb_1.mp3","us":"media/us/announcement__us_1.mp3"}},"angrily":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling strong emotions because you think someone has behaved badly, or because a situation seems bad or unfair","cn":""},{"en":"angry","cn":""}]},"examples":[{"en":"I was angry because he hadn’t told me his plans.","cn":"","src":"ld"},{"en":"He was beginning to get angry .","cn":"","src":"ld"}],"media":{"uk":"media/uk/angrily__gb_1.mp3","us":"media/us/angrily__us_1.mp3"},"oxford":{"phon":"ˈæŋɡrəli","pos":"adverb","senses":[{"en":"in a way that shows you have strong feelings about something that you dislike very much or about an unfair situation","cn":"发怒的；愤怒的；生气的","ex":{"en":"Some senators reacted angrily to the president's remarks.","cn":"一些参议员对总统的言辞感到愤怒，反应强烈。"}}]}},"an":{"media":{"uk":"media/uk/an__gb_1.mp3","us":"media/us/an__us_1.mp3"},"collins":{"senses":[{"pos":"DET 限定词","cn":"（在发音以元音开始的单词前，代替不定冠词a）","en":"An is used instead of 'a', the indefinite article, in front of words that begin with vowel sounds."}]},"examples":[{"en":"an orange","cn":"一个橙子"},{"en":"an X-ray","cn":"一次X光检查"}],"oxford":{"phon":"","pos":"suffix","senses":[{"en":"from; typical of","cn":"来自；有…特征的","ex":{"en":"Libran","cn":"天秤座的"}},{"en":"a specialist in","cn":"专长于…的人；…专家"}]}},"and":{"media":{"uk":"media/uk/and__gb_1.mp3","us":"media/us/and__us_1.mp3"},"oxford":{"phon":"ənd","pos":"conjunction","senses":[{"en":"also; in addition to","cn":"和；与；又；而","ex":{"en":"bread and butter","cn":"涂黄油的面包"}},{"en":"then; following this","cn":"然后；接着","ex":{"en":"She came in and took her coat off.","cn":"她进来后脱了外衣。"}},{"en":"used before a verb instead of to, to show purpose","cn":"（用于动词前代替 to，表示目的）…为了","ex":{"en":"Go and get me a pen please.","cn":"请你去给我拿支钢笔来。"}},{"en":"used to introduce a comment or a question","cn":"（引出评论或问题）","ex":{"en":"‘We talked for hours.’ ‘And what did you decide?’","cn":"“我们谈了好几小时。”“那么你们作出了什么决定？”"}},{"en":"as a result","cn":"（表示结果）结果是；那么；就","ex":{"en":"Miss another class and you'll fail.","cn":"你再缺一次课就会不及格。"}},{"en":"added to","cn":"加；加上","ex":{"en":"5 and 5 makes 10.","cn":"5 加 5 等于 10。"}},{"en":"used between repeated words to show that something is repeated or continuing","cn":"（连接相同的词，表示反复或连续）接连，又，愈来愈","ex":{"en":"He tried and tried but without success.","cn":"他反复尝试，但没有成功。"}},{"en":"used between repeated words to show that there are important differences between things or people of the same kind","cn":"（连接相同的词，强调差别）与…不同，各有不同","ex":{"en":"I like city life but there are cities and cities.","cn":"我喜欢城市生活，但城市之间也有差异。"}}]},"collins":{"senses":[{"pos":"CONJ-COORD 连词","cn":"（连接两个以上的单词、词组或子句）和，与，同","en":"You use and to link two or more words, groups, or clauses.","ex":{"en":"When he returned, she and Simon had already gone","cn":"他回来时，她和西蒙已经走了。"}},{"pos":"CONJ-COORD 连词","cn":"（连接两个相同的单词或短语，以强调某事物的程度、暗示某事继续发生或在一段时间内不断增加）接连，越…越…","en":"You use and to link two words or phrases that are the same in order to emphasize the degree of something, or to suggest that something continues or increases over a period of time.","ex":{"en":"Learning becomes more and more difficult as we get older","cn":"随着年龄增长，学习变得越来越难。"}},{"pos":"CONJ-COORD 连词","cn":"（连接两件相继发生的事件）然后，就","en":"You use and to link two statements about events when one of the events follows the other.","ex":{"en":"I waved goodbye and went down the stone harbour steps","cn":"我挥手告别，然后走下港口石阶。"}},{"pos":"CONJ-COORD 连词","cn":"（连接两句话，第二句话的意思是第一句的延伸）则，而","en":"You use and to link two statements when the second statement continues the point that has been made in the first statement.","ex":{"en":"You could only really tell the effects of the disease in the long term, and five years wasn't long enough","cn":"真的，这种病只能在很久以后才能看出它的影响，而5年的时间还不够长。"}},{"pos":"CONJ-COORD 连词","cn":"（连接两个从句，表示因果关系）那么，于是","en":"You use and to link two clauses when the second clause is a result of the first clause.","ex":{"en":"All through yesterday crowds have been arriving and by midnight thousands of people packed the square.","cn":"昨天陆续有大批人到来，午夜时有几千人聚集在广场上。"}},{"pos":"CONJ-COORD 连词","cn":"（表示停顿，以便对所说的话进行评论）再说，而","en":"You use and to interrupt yourself in order to make a comment on what you are saying.","ex":{"en":"As Downing claims, and as we noted above, reading is best established when the child has an intimate knowledge of the language","cn":"如唐宁所说，也正如我们前文所指出的，当孩子对语言非常熟悉时，阅读的效果最佳。"}},{"pos":"CONJ-COORD 连词","cn":"（用于句首，引出补充说明）还有，不过","en":"You use and at the beginning of a sentence to introduce something else that you want to add to what you have just said. Some people think that starting a sentence with and is ungrammatical, but it is now quite common in both spoken and written English.","ex":{"en":"Commuter airlines fly to out-of-the-way places. And business travelers are the ones who go to those locations.","cn":"支线航空公司航班飞往偏僻地区。商务旅客就是会前往那些地区的人。"}},{"pos":"CONJ-COORD 连词","cn":"（用以引导与某人之谈话有关的问句）那么，还有","en":"You use and to introduce a question which follows logically from what someone has just said.","ex":{"en":"'He used to be so handsome.' — 'And now?'","cn":"“他以前是那么英俊。”——“那么现在呢？”"}},{"pos":"CONJ-COORD 连词","cn":"（广播员等用以转换话题或讨论刚才提及的话题）也","en":"And is used by broadcasters and people making announcements to change a topic or to start talking about a topic they have just mentioned.","ex":{"en":"And now the drought in Sudan","cn":"现在苏丹也有旱情。"}},{"pos":"CONJ-COORD 连词","cn":"（表示两个数字相加）加","en":"You use and to indicate that two numbers are to be added together.","ex":{"en":"What does two and two make?","cn":"2加2等于几？"}},{"pos":"CONJ-COORD 连词","cn":"（用于整数后、分数之前）","en":"And is used before a fraction that comes after a whole number.","ex":{"en":"McCain spent five and a half years in a prisoner of war camp in Vietnam.","cn":"麦凯恩在越南的战俘营里度过了5年半的时间。"}},{"pos":"CONJ-COORD 连词","cn":"（用在大于一百的数字中，置于百位或千位之后，十位及个位之前）","en":"You use and in numbers larger than one hundred, after the words 'hundred' or 'thousand' and before other numbers.","ex":{"en":"We printed two hundred and fifty invitations.","cn":"我们印了250份请柬。"}}]},"examples":[{"en":"‘We talked for hours.’ ‘And what did you decide?’ “","cn":"我们谈了好几小时。” “那么你们作出了什么决定？”"},{"en":"I like city life but there are cities and cities.","cn":"我喜欢城市生活，但城市之间也有差异。"}]},"annually":{"media":{"uk":"media/uk/annually__gb_1.mp3","us":"media/us/annually__us_1.mp3"},"oxford":{"phon":"ˈænjuəli","pos":"adverb","senses":[{"en":"once a year","cn":"一年一次地","ex":{"en":"The exhibition is held annually.","cn":"这个展览每年举行一次。"}}]},"examples":[{"en":"The exhibition is held annually.","cn":"这个展览每年举行一次。"},{"en":"The jazz festival is held annually in July.","cn":"爵士音乐节每年7月举行。"}]},"annoyed":{"media":{"uk":"media/uk/annoyed__gb_1.mp3","us":"media/us/annoyed__us_1.mp3"},"oxford":{"phon":"əˈnɔɪd","pos":"adjective","senses":[{"en":"slightly angry","cn":"恼怒；生气；烦恼","ex":{"en":"He was beginning to get very annoyed with me about my carelessness.","cn":"因为我粗心大意，他已开始恼火了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"生气的；恼怒的","en":"If you are annoyed, you are fairly angry about something.","ex":{"en":"She tapped her forehead and looked annoyed with herself","cn":"她拍打着脑门，看上去在生自己的气。"}}]},"examples":[{"en":"I bet she was annoyed at having to write it out again.","cn":"我敢说她对不得不重写一遍感到恼火。"},{"en":"He was beginning to get very annoyed with me about my carelessness.","cn":"因为我粗心大意，他已开始恼火了。"}]},"anatomy":{"oxford":{"phon":"əˈnætəmi","pos":"noun","senses":[{"en":"the scientific study of the physical structure of humans, animals or plants","cn":"解剖学","g":"[uncountable]","ex":{"en":"the department of anatomy and physiology","cn":"解剖生理学系"}},{"en":"the physical structure of a human, animal or plant","cn":"（动植物的）结构，解剖","g":"[countable, uncountable]","ex":{"en":"the anatomy of the horse","cn":"马的身体构造"}},{"en":"a person’s body","cn":"人体","g":"[countable]","lab":"humorous","ex":{"en":"Various parts of his anatomy were clearly visible.","cn":"他身体的各个部位都清晰可见。"}},{"en":"an examination of what something is like or why it happens","cn":"剖析；解析","g":"[countable]","lab":"formal","ex":{"en":"an anatomy of the current recession","cn":"对当前经济衰退的剖析"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"解剖学","en":"Anatomy is the study of the structure of the bodies of people or animals."},{"pos":"N-COUNT 可数名词","cn":"（人的）身体","en":"You can refer to your body as your anatomy.","ex":{"en":"The ball hit him in the most sensitive part of his anatomy.","cn":"球击中了他身上最敏感的部位。"}},{"pos":"N-COUNT 可数名词","cn":"（动物体的）结构","en":"An animal's anatomy is the structure of its body.","ex":{"en":"He had worked extensively on the anatomy of living animals.","cn":"他在活体解剖方面经验丰富。"}},{"pos":"N-SING 单数名词","cn":"剖析；分析","en":"The anatomy of a subject or an idea is an examination or investigation of it.","ex":{"en":"This was a troubling essay on the anatomy of nationhood.","cn":"这是一篇剖析民族主义的让人不安的文章。"}}]},"media":{"uk":"media/uk/anatomy__gb_1.mp3","us":"media/us/anatomy__us_1.mp3"},"examples":[{"en":"Various parts of his anatomy were clearly visible.","cn":"他身体的各个部位都清晰可见。"},{"en":"an anatomy of the current recession","cn":"对当前衰退的剖析"}]},"anyhow":{"media":{"uk":"media/uk/anyhow__gb_1.mp3","us":"media/us/anyhow__us_1.mp3"},"oxford":{"phon":"ˈenihaʊ","pos":"adverb","senses":[{"en":"used when adding something to support an idea or argument","cn":"而且；加之；反正","lab":"also North American English, informal，，"},{"en":"despite something; even so","cn":"尽管；即使这样","lab":"also North American English, informal，，"},{"en":"used when changing the subject of a conversation, ending the conversation or returning to a subject","cn":"（转换话题、结束谈话或回到原话题时说）不过，总之，反正","lab":"also North American English, informal，，"},{"en":"used to correct or slightly change what you have said","cn":"（纠正或略微改变说过的话）至少","lab":"also North American English, informal，，"},{"en":"in a careless way; not arranged in an order","cn":"随便地；杂乱无章地","ex":{"en":"She piled the papers in a heap on her desk, just anyhow.","cn":"她把文件在桌上随便搁成一堆。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"同anyway","en":"Anyhow means the same as anyway ."},{"pos":"ADV 副词","cn":"马马虎虎地；杂乱无章地","en":"If you do something anyhow, you do it in a careless or untidy way.","ex":{"en":"...her long legs which she displayed all anyhow getting in and out of her car.","cn":"她上下车时不经意露出的长腿"}}]},"examples":[{"en":"She piled the papers in a heap on her desk, just anyhow.","cn":"她把文件在桌上随便搁成一堆。"},{"en":"The scandal could damage her reputation but the press reported it anyhow.","cn":"这宗丑闻可能损害她的名声﹐不过报纸还是给登了出来。"}]},"announcement":{"media":{"uk":"media/uk/announcement__gb_1.mp3","us":"media/us/announcement__us_1.mp3"},"oxford":{"phon":"əˈnaʊnsmənt","pos":"noun","senses":[{"en":"a spoken or written statement that informs people about something","cn":"（一项）公告，布告，通告","g":"[countable]","ex":{"en":"to make an announcement","cn":"发表公告"}},{"en":"the act of publicly informing people about something","cn":"（指行动）宣布，宣告","g":"[uncountable]","ex":{"en":"Announcement of the verdict was accompanied by shouts and cheers.","cn":"在一片喊叫和欢呼声中宣布了正式判决。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"布告;声明;通告","en":"An announcement is a statement made to the public or to the media which gives information about something that has happened or that will happen.","ex":{"en":"Sir Robert made his announcement after talks with the President","cn":"在与总统会谈之后，罗伯特爵士发表了声明。"}},{"pos":"N-SING 单数名词","cn":"宣布;宣告;公布","en":"The announcement of something that has happened is the act of telling people about it.","ex":{"en":"...the announcement of their engagement","cn":"他们订婚消息的宣布"}},{"pos":"N-COUNT 可数名词","cn":"（在报纸、商店橱窗等处刊登的）启事，广告，通告","en":"An announcement in a public place, such as a newspaper or the window of a shop, is a short piece of writing telling people about something or asking for something.","ex":{"en":"He will place an announcement in the personal column of The Daily Telegraph.","cn":"他将在《每日电讯报》的个人专栏上登一则启事。"}}]},"examples":[{"en":"Today's announcement of a peace agreement came after weeks of discussion.","cn":"经过几周的讨论之后，今天公布了和平协议。"},{"en":"Announcement of the verdict was accompanied by shouts and cheers.","cn":"在一片喊叫和欢呼声中宣布了正式判决。"}]},"anticipate":{"media":{"uk":"media/uk/anticipate__gb_1.mp3","us":"media/us/anticipate__us_1.mp3"},"oxford":{"phon":"ænˈtɪsɪpeɪt","pos":"verb","senses":[{"en":"to expect something","cn":"预料；预期","ex":{"en":"We don't anticipate any major problems.","cn":"我们预料不会出现什么大问题。"}},{"en":"to see what might happen in the future and take action to prepare for it","cn":"预见，预计（并做准备）","ex":{"en":"We need someone who can anticipate and respond to changes in the fashion industry.","cn":"我们需要一个能预见时装业变化并做出应对的人。"}},{"en":"to think with pleasure and excitement about something that is going to happen","cn":"期盼；期望","ex":{"en":"We eagerly anticipated the day we would leave school.","cn":"我们迫切地期盼着毕业离校的那一天。"}},{"en":"to do something before it can be done by somebody else","cn":"先于…做；早于…行动","lab":"formal","ex":{"en":"When Scott reached the South Pole he found that Amundsen had anticipated him.","cn":"斯科特到达南极时发现阿蒙森已到过那里。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"预期;预料;预计","en":"If you anticipate an event, you realize in advance that it may happen and you are prepared for it.","ex":{"en":"At the time we couldn't have anticipated the result of our campaigning","cn":"那时我们不可能预料到我们这项运动的结果。"}},{"pos":"VERB 动词","cn":"未待提出就回答（问题）；预先考虑并满足（请求、需要等）","en":"If you anticipate a question, request, or need, you do what is necessary or required before the question, request, or need occurs.","ex":{"en":"What Jeff did was to anticipate my next question","cn":"杰夫预先回答了我的下一个问题。"}},{"pos":"VERB 动词","cn":"早于…做（或想、说）；先于…行动","en":"If you anticipate something, you do it, think it, or say it before someone else does.","ex":{"en":"In the 50s, Rauschenberg anticipated the conceptual art movement of the 80s.","cn":"上世纪50年代时，劳申伯格就早早地预见到了80年代的概念艺术运动。"}}]},"examples":[{"en":"We need someone who can anticipate and respond to changes in the fashion industry.","cn":"我们需要一个能预见时装业变化并做相应安排的人。"},{"en":"When Scott reached the South Pole he found that Amundsen had anticipated him.","cn":"斯科特到达南极时发现阿蒙森已先到过那里。"}]},"anus":{"oxford":{"phon":"ˈeɪnəs","pos":"noun","senses":[{"en":"the opening in a person’s or animal's bottom through which solid waste leaves the body","cn":"肛门"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"肛门","en":"A person's anus is the hole from which faeces leaves their body."}]},"media":{"uk":"media/uk/anus__gb_1.mp3","us":"media/us/anus__us_1.mp3"}},"answer":{"media":{"uk":"media/uk/answer__gb_1.mp3","us":"media/us/answer__us_1.mp3"},"oxford":{"phon":"ˈɑːnsə(r)","pos":"noun","senses":[{"en":"something that you say, write or do to react to a question or situation","cn":"答复；回答","ex":{"en":"I rang the bell, but there was no answer.","cn":"我按了门铃，但没有人应门。"}},{"en":"something that you write or say in reply to a question in a test, an exam, an exercise, etc.; the correct reply to a question in a test, etc.","cn":"（试题、练习等的）答案，正确答案","ex":{"en":"the correct/right answer","cn":"正确答案"}},{"en":"a solution to a problem","cn":"（问题的）解决办法，答案","ex":{"en":"There is no easy answer.","cn":"没有容易的解决办法。"}},{"en":"a person or thing from one place that may be thought to be as good as a famous person or thing from another place","cn":"足以媲美的人；堪称相当的事物","ex":{"en":"The new theme park will be Britain's answer to Disneyland.","cn":"英国新的主题乐园可与迪士尼乐园媲美。"}},{"en":"to say, write or do something as a reaction to a question or situation","cn":"答复；回答","g":"[intransitive, transitive]","ex":{"en":"I repeated the question, but she didn't answer.","cn":"我把问题重复了一遍，但是她仍没有回答。"},"pos":"verb"},{"en":"to defend yourself against a charge or criticism","cn":"为自己辩护；答辩","g":"[transitive]","ex":{"en":"He was summoned before the council to answer charges of treason.","cn":"他被传唤到议会，回应叛国罪的指控。"},"pos":"verb"},{"en":"to be suitable for something; to match something","cn":"适合；符合；比得上；相配","g":"[transitive]","lab":"formal","ex":{"en":"Does this answer your requirements?","cn":"这个符合你的要求吗？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"回答;答复","en":"When you answer someone who has asked you something, you say something back to them.","ex":{"en":"I knew Ben was lying when he answered me","cn":"我知道本回答我时在撒谎。"}},{"pos":"N-COUNT 可数名词","cn":"回答；答复","en":"An answer is something that you say when you answer someone.","ex":{"en":"Without waiting for an answer, he turned and went in through the door","cn":"未等答复，他就转身进了门。"}},{"pos":"PHRASE 短语","cn":"接受反对意见;接受拒绝","en":"If you say that someone will not take no for an answer, you mean that they go on trying to make you agree to something even after you have refused.","ex":{"en":"She is tough, unwilling to take no for an answer","cn":"她很强硬，不达目的誓不罢休。"}},{"pos":"VERB 动词","cn":"回（信）；回复（广告）","en":"If you answer a letter or advertisement, you write to the person who wrote it.","ex":{"en":"Did he answer your letter?","cn":"他给你回信了吗？"}},{"pos":"N-COUNT 可数名词","cn":"回信;复函","en":"An answer is a letter that you write to someone who has written to you.","ex":{"en":"I wrote to him but I never had an answer back","cn":"我写了信给他，但一直没收到回信。"}},{"pos":"VERB 动词","cn":"接（电话）；应（门）；应答","en":"When you answer the telephone, you pick it up when it rings. When you answer the door, you open it when you hear a knock or the bell.","ex":{"en":"She answered her phone on the first ring","cn":"电话刚一响，她就接了。"}},{"pos":"N-COUNT 可数名词","cn":"解决办法","en":"An answer to a problem is a solution to it.","ex":{"en":"There are no easy answers to the problems facing the economy","cn":"解决经济所面临的问题并非易事。"}},{"pos":"N-COUNT 可数名词","cn":"答案","en":"Someone's answer to a question in a test or quiz is what they write or say in an attempt to give the facts that are asked for. The answer to a question is the fact that was asked for.","ex":{"en":"Simply marking an answer wrong will not help the pupil to get future examples correct","cn":"仅仅在答案上打叉号不会有助于学生做对日后的题目。"}},{"pos":"VERB 动词","cn":"解答;答（题）","en":"When you answer a question in a test or quiz, you write or say something in an attempt to give the facts that are asked for.","ex":{"en":"To obtain her degree, she answered 81 questions over 10 papers.","cn":"为获得学位，她回答了10页纸上的81个问题。"}},{"pos":"N-COUNT 可数名词","cn":"反应；回报；回应；反击","en":"Your answer to something that someone has said or done is what you say or do in response to it or in defence of yourself.","ex":{"en":"In answer to speculation that she wouldn't finish the race, she boldly declared her intention of winning it.","cn":"为了回应她会中途退赛的猜测，她大胆地宣布她要赢得这场比赛。"}},{"pos":"VERB 动词","cn":"反应;回报;回应;反击","en":"If you answer something that someone has said or done, you respond to it.","ex":{"en":"He answered her smile with one of his own","cn":"他对她的微笑回以同礼。"}},{"pos":"N-SING 单数名词","cn":"（某地）与…相似的东西，相当于…的东西","en":"If you say that something is a place's answer to a famous thing, you mean that the first thing is the equivalent of the second in that place.","ex":{"en":"Cachaca is Brazil's answer to tequila.","cn":"巴西甜酒相当于是巴西的龙舌兰酒。"}},{"pos":"VERB 动词","cn":"满足，适合，符合（需要、目的）","en":"If something answers a need or purpose, it satisfies it, because it has the right qualities.","ex":{"en":"We provide specially designed shopping trolleys to answer the needs of parents with young children.","cn":"我们提供特别设计的购物车，以满足带幼儿的父母的需要。"}},{"pos":"VERB 动词","cn":"与…相符；符合","en":"If someone or something answers a particular description or answers to it, they have the characteristics described.","ex":{"en":"Two men answering the description of the suspects tried to enter Switzerland","cn":"与描述的疑犯样子相符的两名男子试图进入瑞士。"}},{"pos":"","cn":"","en":"相关词组：answer back answer for"}]},"examples":[{"en":"As if in answer to our prayers, she offered to lend us £10 000.","cn":"好像祈祷很灵验似的，她提出借给我们 1 万英镑。"},{"en":"Answer me this: how did they know we were here?","cn":"回答我这个问题：他们怎么知道我们在这儿？"}]},"animal":{"media":{"uk":"media/uk/animal__gb_1.mp3","us":"media/us/animal__us_1.mp3"},"oxford":{"phon":"ˈænɪml","pos":"noun","senses":[{"en":"a creature that is not a bird, a fish, a reptile, an insect or a human","cn":"兽；牲畜；动物（不包括鸟、鱼、爬行动物、昆虫和人）","ex":{"en":"the animals and birds of South America","cn":"南美的鸟兽"}},{"en":"any living thing that is not a plant or a human","cn":"动物（不包括植物和人的生物）","ex":{"en":"This product has not been tested on animals.","cn":"这种产品尚未在动物身上试验。"}},{"en":"any living creature, including humans","cn":"动物（包括人）","ex":{"en":"Humans are the only animals to have developed speech.","cn":"人是唯一发展出语言的动物。"}},{"en":"a person who behaves in a cruel or unpleasant way, or who is very dirty","cn":"衣冠禽兽；残暴的人；卑鄙下流的人","ex":{"en":"The person who did this is an animal, a brute.","cn":"干这种事的人是畜生，是野兽。"}},{"en":"a particular type of person, thing, organization, etc.","cn":"某类型的人（或事物、机构等）","ex":{"en":"She's not a political animal.","cn":"她不是搞政治的那种人。"}},{"en":"relating to the physical needs and basic feelings of people","cn":"肉体的；肉欲的；情欲的","ex":{"en":"animal desires/passion/instincts","cn":"兽欲；肉欲激情；情欲本能"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（除鸟、鱼、昆虫或人类之外的）动物，兽类","en":"An animal is a living creature such as a dog, lion, or rabbit, rather than a bird, fish, insect, or human being.","ex":{"en":"He was attacked by wild animals","cn":"他遭到野兽的袭击。"}},{"pos":"N-COUNT 可数名词","cn":"动物（泛指人类以外的任何生物）","en":"Any living creature other than a human being can be referred to as an animal .","ex":{"en":"Language is something which fundamentally distinguishes humans from animals.","cn":"语言是将人类与动物区分开来的基本特征。"}},{"pos":"N-COUNT 可数名词","cn":"动物（包括人类在内的任何生物）","en":"Any living creature, including a human being, can be referred to as an animal .","ex":{"en":"Watch any young human being, or any other young animal.","cn":"注意儿童或其他幼小动物。"}},{"pos":"ADJ 形容词","cn":"动物的；野兽的；取自动物的","en":"Animal products come from animals rather than from plants.","ex":{"en":"The illegal trade in animal products continues to flourish","cn":"野生动物制品的非法交易仍旧猖獗。"}},{"pos":"N-COUNT 可数名词","cn":"禽兽;野蛮的人","en":"If you say that someone is an animal, you find their behaviour disgusting or very unpleasant.","ex":{"en":"This man is an animal, a beast","cn":"这人是个畜生，是个野兽。"}},{"pos":"ADJ 形容词","cn":"肉体的；肉欲的；动物的；非理性的","en":"Animal qualities, feelings, or abilities relate to someone's physical nature and instincts rather than to their mind.","ex":{"en":"There was no doubting the animal magnetism of the man","cn":"这个男人无疑有一种野性的魅力。"}},{"pos":"N-COUNT 可数名词","cn":"…类型的人;有特殊兴趣的人","en":"You can refer to someone as a particular type of animal in order to say what their interests are or what their typical behaviour is.","ex":{"en":"You're quite a party animal aren't you, out there every night","cn":"你就是为派对而生的，不是吗，每天晚上你都去参加派对。"}}]},"examples":[{"en":"The government that followed the election was a very different animal.","cn":"选举后的政府与前一届截然不同。"},{"en":"This product has not been tested on animals.","cn":"这种产品尚未在动物身上试验。"}]},"angle":{"oxford":{"phon":"ˈæŋɡl","pos":"noun","senses":[{"en":"the space between two lines or surfaces that join, measured in degrees","cn":"角","ex":{"en":"a 45° angle","cn":"45° 角"}},{"en":"a corner on the outside or inside of something","cn":"角","ex":{"en":"It's a modern building, all brick and glass and sharp angles.","cn":"这是一座现代建筑，整体由砖和玻璃建成，棱角分明。"}},{"en":"the direction that something is leaning or pointing in when it does not go straight up and down or straight across from side to side","cn":"斜角；角度","ex":{"en":"The Tower of Pisa leans at an angle.","cn":"比萨斜塔塔身倾斜。"}},{"en":"a position from which you look at something","cn":"角度","ex":{"en":"The photo was taken from an unusual angle.","cn":"这张照片是从不寻常的角度拍摄的。"}},{"en":"a particular way of presenting or thinking about a situation, problem, etc.","cn":"观点；立场；角度","ex":{"en":"We need a new angle for our next advertising campaign.","cn":"我们需要从一个新的角度去展开下一次广告活动。"}},{"en":"to move or place something so that it is not straight or not directly facing somebody/something","cn":"斜移；斜置","g":"[transitive]","ex":{"en":"He angled his chair so that he could sit and watch her.","cn":"他斜移了椅子，以便坐着观察她。"},"pos":"verb"},{"en":"to present information, a report, etc. based on a particular way of thinking or for a particular audience","cn":"以（某角度）报道；以（某观点）提供信息","g":"[transitive]","ex":{"en":"The programme is angled towards younger viewers.","cn":"这个节目的对象是较年轻的观众。"},"pos":"verb"},{"en":"to catch fish with a line and a hook","cn":"垂钓；钓鱼","g":"[intransitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"角；角度","en":"An angle is the difference in direction between two lines or surfaces. Angles are measured in degrees.","ex":{"en":"The boat is now leaning at a 30 degree angle.","cn":"船正以30度角倾斜。"}},{"pos":"N-COUNT 可数名词","cn":"（两条线或两个平面相交的）夹角，边角","en":"An angle is the shape that is created where two lines or surfaces join together.","ex":{"en":"...the angle of the blade.","cn":"刀口的夹角"}},{"pos":"N-COUNT 可数名词","cn":"角度","en":"An angle is the direction from which you look at something.","ex":{"en":"Thanks to the angle at which he stood, he could just see the sunset","cn":"由于站的位置视角好，他刚好能看见日落。"}},{"pos":"N-COUNT 可数名词","cn":"角度；观点；立场；侧重点；倾向性","en":"You can refer to a way of presenting something or thinking about it as a particular angle .","ex":{"en":"We had to do the scene over and over again, from different angles","cn":"我们不得不翻来覆去地从不同的角度拍这个场面。"}},{"pos":"VERB 动词","cn":"（间接迂回地）猎取，谋取，博取","en":"If someone is angling for something, they are trying to get it without asking for it directly.","ex":{"en":"It sounds as if he's just angling for sympathy.","cn":"听起来好像他只是在博取同情。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）朝向；（使）转向","en":"If you angle something or if it angles in a particular direction, it faces or points in that direction.","ex":{"en":"You can open the slats for a bright light or angle them for more shade","cn":"可以调节百叶窗使光线亮一些，也可以暗一些。"}},{"pos":"PHRASE 短语","cn":"成角度的;歪的;斜的","en":"If something is at an angle, it is leaning in a particular direction so that it is not straight, horizontal, or vertical.","ex":{"en":"An iron bar stuck out at an angle","cn":"一根铁棍斜伸出来。"}}]},"media":{"img":["media/pic/angles_comp.jpg","media/thumb/rightangle.jpg"],"uk":"media/uk/angle__gb_1.mp3","us":"media/us/angle__us_1.mp3"},"examples":[{"en":"We need a new angle for our next advertising campaign.","cn":"我们需要从一个新的角度去展开下一次广告活动。"},{"en":"The article concentrates on the human angle (= the part that concerns people's emotions) of the story.","cn":"这篇文章集中讨论了故事中人的情感问题。"}]},"anticipatory":{"media":{"uk":"media/uk/anticipatory__gb_1.mp3","us":"media/us/anticipatory__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"期待的；期望的；预期的","en":"An anticipatory feeling or action is one that you have or do because you are expecting something to happen soon.","ex":{"en":"...an anticipatory smile.","cn":"期许的笑容"}}]},"examples":[{"en":"( formal ) a fast anticipatory movement by the goalkeeper","cn":"守门员的快速预期动作"},{"en":"Sales are better than anticipated.","cn":""}],"oxford":{"phon":"ænˌtɪsɪˈpeɪtəri","pos":"adjective","senses":[{"en":"done in order to prepare for something that you think might happen","cn":"预先的","ex":{"en":"a fast anticipatory movement by the goalkeeper","cn":"守门员的快速预判动作"}}]}},"anthropology":{"oxford":{"phon":"ˌænθrəˈpɒlədʒi","pos":"noun","senses":[{"en":"the study of the human race, especially of its origins, development, customs and beliefs","cn":"人类学","ex":{"en":"Social anthropology examines family relationships in detail.","cn":"社会人类学详尽地探讨家庭关系。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"人类学","en":"Anthropology is the scientific study of people, society, and culture."}]},"media":{"uk":"media/uk/anthropology__gb_1.mp3","us":"media/us/anthropology__us_1.mp3"}},"anonymity":{"media":{"uk":"media/uk/anonymity__gb_1.mp3","us":"media/us/anonymity__us_1.mp3"},"oxford":{"phon":"ˌænəˈnɪməti","pos":"noun","senses":[{"en":"the state of remaining unknown to most other people","cn":"匿名；不知姓名；名字不公开","lab":"especially North American English","ex":{"en":"Names of people in the book were changed to preserve anonymity.","cn":"为了姓名保密，书中的人用的都是化名。"}},{"en":"the state of not having any unusual or interesting features","cn":"无特色；无个性特征","ex":{"en":"the anonymity of the hotel decor","cn":"这家旅馆毫无特色的装饰风格"}}]},"examples":[{"en":"Names of people in the book were changed to preserve anonymity.","cn":"为了姓名保密，书中的人用的都是化名。"},{"en":"( especially NAmE ) He agreed to give an interview on condition of anonymity (= if his name was not mentioned).","cn":"他同意在不披露姓名的条件下接受采访。"}]},"angry":{"media":{"uk":"media/uk/angry__gb_1.mp3","us":"media/us/angry__us_1.mp3"},"oxford":{"phon":"ˈæŋɡri","pos":"adjective","senses":[{"en":"having strong feelings about something that you dislike very much or about an unfair situation","cn":"发怒的；愤怒的；生气的","lab":"especially North American English","ex":{"en":"Her behaviour really made me angry.","cn":"她的行为确实令我恼火。"}},{"en":"red and painful, usually because of an infection","cn":"（常指因感染）红肿的，发炎的"},{"en":"dark and stormy","cn":"狂风暴雨的；波涛汹涌的；天昏地暗的","lab":"literary","ex":{"en":"the angry sea with its terrible waves","cn":"愤怒的大海和可怕的波浪"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"发怒的；生气的；愤怒的","en":"When you are angry, you feel strong dislike or impatience about something.","ex":{"en":"She had been very angry at the person who stole her new bike","cn":"她很生气有人偷走了她的新自行车。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（伤口或疹子）肿痛的，红肿的","en":"An angry wound or rash is red and painful.","ex":{"en":"He was badly concussed, the glass leaving two angry cuts across his forehead.","cn":"他遭受了严重的脑震荡，脑门上留下的两道被玻璃划破的口子已经红肿。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天空或海洋）天昏地暗的，狂风暴雨的","en":"If you describe the sky or sea as angry, you mean that it is dark and stormy."}]},"examples":[{"en":"Some senators reacted angrily to the President's remarks.","cn":"一些参议员对总统的言辞感到愤怒，反应强烈。"},{"en":"I was very angry with myself for making such a stupid mistake.","cn":"我很生自己的气，竟犯了这样愚蠢的错误。"}]},"analogous":{"media":{"uk":"media/uk/analogous__gb_1.mp3","us":"media/us/analogous__us_1.mp3"},"oxford":{"phon":"əˈnæləɡəs","pos":"adjective","senses":[{"en":"similar in some way to another thing or situation and therefore able to be compared with it","cn":"相似的；类似的","ex":{"en":"Sleep has often been thought of as being in some way analogous to death.","cn":"人们常常认为睡眠在某种意义上来说类似死亡。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"相似的；类似的；可比拟的","en":"If one thing is analogous to another, the two things are similar in some way.","ex":{"en":"Marine construction technology like this is very complex, somewhat analogous to trying to build a bridge under water.","cn":"像这样的海底建造技术很复杂，与尝试在水下建桥有些相似。"}}]},"examples":[{"en":"Sleep has often been thought of as being in some way analogous to death.","cn":"人们常常认为睡眠在某种意义上来说类似死亡。"},{"en":"The report’s findings are analogous with our own.","cn":"这篇报告的发现与我们的类似。"}]},"anxious":{"media":{"uk":"media/uk/anxious__gb_1.mp3","us":"media/us/anxious__us_1.mp3"},"oxford":{"phon":"ˈæŋkʃəs","pos":"adjective","senses":[{"en":"feeling worried or nervous","cn":"焦虑；忧虑；担心","ex":{"en":"The bus was late and Sue began to get anxious.","cn":"公共汽车晚点了，休开始感到焦虑。"}},{"en":"causing worry; showing worry","cn":"令人焦虑的；流露出忧虑的","ex":{"en":"The family faces another anxious wait for news.","cn":"这家人再次焦虑地等候消息。"}},{"en":"wanting something very much","cn":"渴望；非常希望","ex":{"en":"She was anxious to finish school and get a job.","cn":"她渴望毕业，然后找一份工作。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"渴望的;急切的","en":"If you are anxious to do something or anxious that something should happen, you very much want to do it or very much want it to happen.","ex":{"en":"Both the Americans and the Russians are anxious to avoid conflict in South Asia","cn":"美国人和俄罗斯人都迫切希望避免在南亚发生冲突。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"焦虑的;忧虑的;不安的","en":"If you are anxious, you are nervous or worried about something.","ex":{"en":"The foreign minister admitted he was still anxious about the situation in the country","cn":"外交部长承认对于该国的局势他仍然颇感忧虑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（时间或局势）紧张的，令人焦虑的，让人担忧的","en":"An anxious time or situation is one during which you feel nervous and worried.","ex":{"en":"The Prime Minister faces anxious hours before the votes are counted tomorrow night.","cn":"在明晚计票完成之前，首相将面临数小时的煎熬等待。"}}]},"examples":[{"en":"There were a few anxious moments in the baseball game.","cn":"那场棒球赛中有些时刻令人焦虑不安。"},{"en":"He seemed anxious about the meeting.","cn":"他似乎对这次会议忧心忡忡。"}]},"ancient":{"media":{"uk":"media/uk/ancient__gb_1.mp3","us":"media/us/ancient__us_1.mp3"},"oxford":{"phon":"ˈeɪnʃənt","pos":"adjective","senses":[{"en":"belonging to a period of history that is thousands of years in the past","cn":"古代的","ex":{"en":"Archaeologists are excavating the ruined temples of this ancient civilization.","cn":"考古学家正在挖掘这个古老文明的神庙遗址。"}},{"en":"very old; having existed for a very long time","cn":"古老的；很老的","lab":"humorous","ex":{"en":"an ancient oak tree","cn":"古橡树"}},{"en":"the people who lived in ancient times, especially the Egyptians, Greeks and Romans","cn":"（尤指古埃及、古希腊和古罗马的）古代人","g":"[plural]"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"远古的；古代的","en":"Ancient means belonging to the distant past, especially to the period in history before the end of the Roman Empire.","ex":{"en":"They believed ancient Greece and Rome were vital sources of learning.","cn":"他们认为古代希腊罗马是知识的重要发源地。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"古老的；年代久远的","en":"Ancient means very old, or having existed for a long time.","ex":{"en":"...ancient Jewish tradition.","cn":"古老的犹太传统"}},{"pos":"N-PLURAL 复数名词","cn":"古代人；（尤指）古希腊人，古罗马人","en":"The ancients are the people of an old civilization, especially classical Greece or Rome.","ex":{"en":"The ancients knew more than we do about the heavens.","cn":"古代人对于上天比我们知道得多。"}}]},"examples":[{"en":"( humorous ) He's ancient — he must be at least fifty!","cn":"他老得很了 — 肯定至少有五十岁！"},{"en":"the area where the market was anciently held (= in ancient times)","cn":"古代集市所在地"}]},"anthropoid":{"media":{"uk":"media/uk/anthropoid__gb_1.mp3","us":"media/us/anthropoid__us_1.mp3"},"oxford":{"phon":"ˈænθrəpɔɪd","pos":"adjective","senses":[{"en":"looking like a human","cn":"类人的；似人的"},{"en":"any type of ape that is similar to a human","cn":"类人猿","ex":{"en":"a theory about how man developed from being among the higher anthropoids to being human","cn":"关于人类如何从高等类人猿进化为人类的理论"},"pos":"noun"}]}},"another":{"media":{"uk":"media/uk/another__gb_1.mp3","us":"media/us/another__us_1.mp3"},"oxford":{"phon":"əˈnʌðə(r)","pos":"determiner, pronoun","senses":[{"en":"one more; an extra thing or person","cn":"又一；再一；另一（事物或人）","ex":{"en":"Would you like another drink?","cn":"还想喝一杯吗？"}},{"en":"different; a different person or thing","cn":"另一；不同的（人或事物）","ex":{"en":"Let's do it another time.","cn":"咱们下次再办这件事吧。"}},{"en":"a person or thing of a very similar type","cn":"类似的（人或事物）","ex":{"en":"She's going to be another Madonna (= as famous as her).","cn":"她就要变得跟麦当娜一般出名了。"}}]},"collins":{"senses":[{"pos":"DET 限定词","cn":"（同类事物中的）另一个，再一个","en":"Another thing or person means an additional thing or person of the same type as one that already exists.","ex":{"en":"Mrs. Madrigal buttered another piece of toast","cn":"马德里加尔夫人给另一片烤面包涂上了黄油。"}},{"pos":"DET 限定词","cn":"另一个;不同的;别的","en":"You use another when you want to emphasize that an additional thing or person is different to one that already exists.","ex":{"en":"I think he's just going to deal with this problem another day","cn":"我想他改天就会处理这个问题。"}},{"pos":"DET 限定词","cn":"（与前面的陈述相连）另一（个）","en":"You use another at the beginning of a statement to link it to a previous statement.","ex":{"en":"Another time of great excitement for us boys was when war broke out","cn":"对我们男孩子来说另一个极度刺激的时刻是战争爆发。"}},{"pos":"DET 限定词","cn":"（用在距离、时间段或其他量词之前）又…的，再…的","en":"You use another before a word referring to a distance, length of time, or other amount, to indicate an additional amount.","ex":{"en":"Continue down the same road for another 2 kilometres until you reach the church of Santa Maria","cn":"沿同一条路再往前走两公里，直至到达圣马丽亚教堂。"}},{"pos":"DET 限定词","cn":"（用于有名的人物、地点或事件前表示与其类似的）另一个…，类似…的","en":"You use another in front of the name of a well-known person, place, or event to indicate that you think someone or something is just like that person, place, or event.","ex":{"en":"You may never be another Hemingway, but you can learn to write well.","cn":"你可能成不了第二个海明威，但你可以练就一手好文笔。"}},{"pos":"PRON-RECIP 相互代词","cn":"互相","en":"You use one another to indicate that each member of a group does something to or for the other members.","ex":{"en":"...women learning to help themselves and one another","cn":"学着自助和互助的妇女们"}},{"pos":"PHRASE 短语","cn":"一个接一个地；接连地","en":"If you talk about one thing after another, you are referring to a series of repeated or continuous events.","ex":{"en":"They had faced one difficulty after another with bravery and dedication","cn":"他们以无畏和无私奉献的精神迎接了一个又一个的困难。"}},{"pos":"PHRASE 短语","cn":"（表示不确指）各种不同的，各种各样的","en":"You use or another in expressions such as one kind or another when you do not want to be precise about which of several alternatives or possibilities you are referring to.","ex":{"en":"...family members and visiting artists of one kind or another crowding the huge kitchen","cn":"聚集在这个宽敞厨房里的家庭成员和来访的各类艺术家"}}]},"examples":[{"en":"‘Finished?’ ‘No, I've got another three questions to do.’ “","cn":"做完了？” “没有，我还有三个问题要解答。”"},{"en":"We can try that — but whether it'll work is another matter.","cn":"我们可以试试看，但行不行则是另一回事。"}]},"any":{"media":{"uk":"media/uk/any__gb_1.mp3","us":"media/us/any__us_1.mp3"},"oxford":{"phon":"ˈeni","pos":"determiner","senses":[{"en":"used with uncountable or plural nouns in negative sentences and questions, after if or whether, and after some verbs such as prevent, ban, forbid, etc. to refer to an amount or a number of something, however large or small","cn":"（与不可数或复数名词连用，用于否定句和疑问句，也用于 if 或 whether 之后，或紧接某些动词如 prevent、ban、forbid 等）任何的，任一的","ex":{"en":"I didn't eat any meat.","cn":"我一点儿肉也没吃。"}},{"en":"used with singular countable nouns to refer to one of a number of things or people, when it does not matter which one","cn":"（与单数可数名词连用）任一","ex":{"en":"Take any book you like.","cn":"你喜欢哪本书就拿哪本。"}},{"en":"used to show that somebody/something is special","cn":"非一般的；不寻常的","ex":{"en":"It isn't just any day—it's my birthday!","cn":"今天不是一般的日子，是我的生日！"}},{"en":"used in negative sentences and in questions and after if or whether to refer to an amount or a number, however large or small","cn":"（用于否定句和疑问句中或 if、whether 后）任何数量，任一数额","ex":{"en":"We need some more paint; there isn't any left.","cn":"我们还需要一些油漆，已经用光了。"},"pos":"pronoun"},{"en":"one or more of a number of people or things, especially when it does not matter which","cn":"任一；任何一些","ex":{"en":"I'll take any you don't want.","cn":"你不要的我拿走。"},"pos":"pronoun"},{"en":"used to emphasize an adjective or adverb in negative sentences or questions, meaning ‘at all’","cn":"（用于否定句或疑问句中，加强形容词或副词的语气）一点儿也（不），完全（不），丝毫","ex":{"en":"He wasn't any good at French.","cn":"他的法语糟透了。"},"pos":"adverb"},{"en":"used at the end of a negative sentence to mean ‘at all’","cn":"（用于否定句末）根本（不）","lab":"North American English, informal，，","ex":{"en":"That won't hurt you any.","cn":"那根本不会伤害你。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"DET 限定词","cn":"（用于否定句）一点，丝毫，若干，任何","en":"You use any in statements with negative meaning to indicate that no thing or person of a particular type exists, is present, or is involved in a situation.","ex":{"en":"I never make any big decisions","cn":"我从未作过任何重大决定。"}},{"pos":"DET 限定词","cn":"（用于疑问句或条件从句）若干，一点，什么，任何一个（或一些）","en":"You use any in questions and conditional clauses to ask whether there is some of a particular thing or some of a particular group of people, or to suggest that there might be.","ex":{"en":"Do you speak any foreign languages?","cn":"你会说外语吗？"}},{"pos":"DET 限定词","cn":"（用于肯定句）任一的，每一的","en":"You use any in positive statements when you are referring to someone or something of a particular kind that might exist, occur, or be involved in a situation, when their exact identity or nature is not important.","ex":{"en":"Any actor will tell you that it is easier to perform than to be themselves","cn":"每一个演员都会告诉你演戏比做自己容易。"}},{"pos":"ADV 副词","cn":"（用于否定句中强调形容词或副词的比较级）任何，丝毫，略微，多少","en":"You can also use any to emphasize a comparative adjective or adverb in a negative statement.","ex":{"en":"I can't see things getting any easier for graduates","cn":"我没看出毕业生的境遇有丝毫好转。"}},{"pos":"PHRASE 短语","cn":"（人或物）很特别的，不普通的","en":"If you say that someone or something is not just any person or thing, you mean that they are special in some way.","ex":{"en":"Finzer is not just any East Coast businessman","cn":"芬泽不是个普通的东海岸生意人。"}},{"pos":"PHRASE 短语","cn":"（不）再","en":"If something does not happen or is not true any more or any longer, it has stopped happening or is no longer true.","ex":{"en":"I don't want to see her any more","cn":"我不想再见到她。"}},{"pos":"","cn":"","en":"→see: ; →see: ; by any chance→see: ; in any event→see: ; not by any means→see: ; any old→see: ; at any rate→see: ;"}]},"examples":[{"en":"‘Which colour do you want?’ ‘Any of them will do.’ “","cn":"你要哪种颜色？” “随便哪种都行。”"},{"en":"Please let me know how many people are coming, if any.","cn":"如果有人要来的话，请告诉我有多少。"}]},"animosity":{"media":{"uk":"media/uk/animosity__gb_1.mp3","us":"media/us/animosity__us_1.mp3"},"oxford":{"phon":"ˌænɪˈmɒsəti","pos":"noun","senses":[{"en":"a strong feeling of opposition, anger or hate","cn":"仇恨；愤怒；敌意；憎恶","ex":{"en":"He felt no animosity towards his critics.","cn":"他对批评他的人并不心怀怨恨。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"敌意；怨恨；憎恶","en":"Animosity is a strong feeling of dislike and anger. Animosities are feelings of this kind.","ex":{"en":"There's a long history of animosity between the two nations","cn":"两国之间宿怨已久。"}}]},"examples":[{"en":"He felt no animosity towards his critics.","cn":"他对批评他的人并不心怀怨恨。"},{"en":"personal animosities between members of the two groups","cn":"两个集团成员之间的私仇"}]},"antivirus":{"media":{"uk":"media/uk/antivirus__gb_1.mp3","us":"media/us/antivirus__us_1.mp3"},"oxford":{"phon":"ˈæntivaɪrəs","pos":"adjective","senses":[{"en":"designed to find and destroy computer viruses","cn":"防病毒的；杀毒的","ex":{"en":"antivirus software","cn":"防病毒软件"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（软件）杀毒的，防病毒的","en":"Anti-virus software is software that protects a computer against viruses."}]},"examples":[{"en":"antivirus software","cn":"杀毒软件"}]},"annoy":{"media":{"uk":"media/uk/annoy__gb_1.mp3","us":"media/us/annoy__us_1.mp3"},"oxford":{"phon":"əˈnɔɪ","pos":"verb","senses":[{"en":"to make somebody slightly angry","cn":"使恼怒；使生气","ex":{"en":"His constant joking was beginning to annoy her.","cn":"他不停地开玩笑，已开始惹她生气。"}},{"en":"to make somebody uncomfortable or unable to relax","cn":"打扰；骚扰","ex":{"en":"He swatted a fly that was annoying him.","cn":"他猛力拍打一只搅得他心烦的苍蝇。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使生气；使不耐烦；使烦恼","en":"If someone or something annoys you, it makes you fairly angry and impatient.","ex":{"en":"Try making a note of the things which annoy you","cn":"试着把烦心事写下来。"}}]},"examples":[{"en":"It really annoys me when people forget to say thank you.","cn":"有人连谢谢都忘记说时我确实感到不愉快。"},{"en":"His constant joking was beginning to annoy her.","cn":"他不停地开玩笑，已开始惹她生气。"}]},"angles":{"oxford":{"phon":"ˈæŋɡl","pos":"noun","senses":[{"en":"the space between two lines or surfaces that join, measured in degrees","cn":"角"},{"en":"the direction that sth is leaning or pointing in when it is not in a vertical or horizontal line","cn":"斜角；角度"}]},"media":{"img":["media/pic/angles_comp.jpg"]}},"anthropologist":{"media":{"uk":"media/uk/anthropologist__gb_1.mp3","us":"media/us/anthropologist__us_1.mp3"},"oxford":{"phon":"ˌænθrəˈpɒlədʒɪst","pos":"noun","senses":[{"en":"a person who studies the human race, especially its origins, development, customs and beliefs","cn":"人类学家"}]}},"ancestral":{"media":{"uk":"media/uk/ancestral__gb_1.mp3","us":"media/us/ancestral__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"祖先的；祖传的","en":"You use ancestral to refer to a person's family in former times, especially when the family is important and has property or land which they have had for a long time.","ex":{"en":"...the family's ancestral home in southern Germany.","cn":"这个家族在德国南部的祖居"}}]},"examples":[{"en":"her ancestral home (= that had belonged to her ancestors )","cn":"她的祖居"},{"en":"My ancestors were French.","cn":""}],"oxford":{"phon":"ænˈsestrəl","pos":"adjective","senses":[{"en":"connected with or that belonged to people in your family who lived a long time ago","cn":"祖宗；祖先","ex":{"en":"her ancestral home","cn":"她的祖居"}}]}},"announce":{"media":{"uk":"media/uk/announce__gb_1.mp3","us":"media/us/announce__us_1.mp3"},"oxford":{"phon":"əˈnaʊns","pos":"verb","senses":[{"en":"to tell people something officially, especially about a decision, plans, etc.","cn":"宣布，宣告（决定、计划等）","lab":"figurative","ex":{"en":"He officially announced his intention to resign at today's press conference.","cn":"在今天的记者招待会上，他正式宣布了辞职计划。"}},{"en":"to give information about something in a public place, especially through a loudspeaker","cn":"（尤指通过广播）通知","ex":{"en":"Has our flight been announced yet?","cn":"广播通知了我们的航班没有？"}},{"en":"to say something in a loud and/or serious way","cn":"声称；宣称","ex":{"en":"‘I've given up smoking,’ she announced.","cn":"“我戒烟了。”她郑重其事地说。"}},{"en":"to tell somebody your name or somebody else’s name when you or they arrive at a place","cn":"宣布（某人）到达；通报…的到来","ex":{"en":"Would you announce the guests as they arrive? (= call out their names, for example at a formal party)","cn":"客人到达时请你通报他们的姓名好吗？"}},{"en":"to introduce, or to give information about, a programme on the radio or television","cn":"（在广播或电视中）播音，广播"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"宣布;宣告;公布","en":"If you announce something, you tell people about it publicly or officially.","ex":{"en":"He will announce tonight that he is resigning from office","cn":"他将于今晚宣布辞职。"}},{"pos":"VERB 动词","cn":"大声宣告，郑重地说（尤指令人不快之事）","en":"If you announce a piece of news or an intention, especially something that people may not like, you say it loudly and clearly, so that everyone you are with can hear it.","ex":{"en":"Peter announced that he had no intention of wasting his time at any university","cn":"彼得宣称他无意在任何一所大学浪费时间。"}},{"pos":"VERB 动词","cn":"（机场或火车站工作人员通过扬声器）播报，通知","en":"If an airport or railway employee announces something, they tell the public about it by means of a loudspeaker system.","ex":{"en":"Station staff announced the arrival of the train over the tannoy","cn":"车站工作人员通过广播告知火车到站了。"}},{"pos":"VERB 动词","cn":"（以信件、声音、信号等）通知，告知","en":"If a letter, sound, or sign announces something, it informs people about it.","ex":{"en":"The next letter announced the birth of another boy","cn":"下一封信通知又一个男孩出生了。"}},{"pos":"VERB 动词","cn":"（仆人）通报，宣布（膳食备齐或来宾到达）","en":"If a meal or a guest is announced by a servant at a formal party, the servant says clearly that the meal is ready or the guest has arrived.","ex":{"en":"Dinner was announced, and served.","cn":"已宣布开饭了，菜都上齐了。"}}]},"examples":[{"en":"‘Now boarding flight 897, destination Seattle,’ the loudspeaker announced. “","cn":"飞往西雅图的 897 次航班现在开始登机。”广播通知说。"},{"en":"The government yesterday announced to the media plans to create a million new jobs.","cn":"政府在昨天向媒体宣布了创造一百万个新工作的计划。"}]},"anywhere":{"media":{"uk":"media/uk/anywhere__gb_1.mp3","us":"media/us/anywhere__us_1.mp3"},"oxford":{"phon":"ˈeniweə(r)","pos":"adverb","senses":[{"en":"used in negative sentences and in questions instead of somewhere","cn":"（用于否定句和疑问句，代替 somewhere）任何地方","ex":{"en":"I can't see it anywhere.","cn":"我哪儿也见不到它。"}},{"en":"in, at or to any place, when it does not matter where","cn":"在（或去）任何地方；随便哪个地方","ex":{"en":"Put the box down anywhere.","cn":"把箱子随便放在哪儿都可以。"}},{"en":"used in negative sentences and in questions instead of somewhere","cn":"（用于否定句和疑问句，代替 somewhere）任何地方","ex":{"en":"I don't have anywhere to stay.","cn":"我没有地方住。"},"pos":"pronoun"}]},"collins":{"senses":[{"pos":"ADV-INDEF 不定副词","cn":"（用于否定句）哪儿，到处（都没有）","en":"You use anywhere in statements with negative meaning to indicate that a place does not exist.","ex":{"en":"I haven't got anywhere to live","cn":"我还没找到住的地方。"}},{"pos":"ADV-INDEF 不定副词","cn":"（用于疑问句和条件从句）某个地方，哪里","en":"You use anywhere in questions and conditional clauses to ask or talk about a place without saying exactly where you mean.","ex":{"en":"Did you try to get help from anywhere?","cn":"你尝试过从哪里寻求帮助吗？"}},{"pos":"ADV-INDEF 不定副词","cn":"（用于描述所谈论的某个地方的词语前）…地方","en":"You use anywhere before words that indicate the kind of place you are talking about.","ex":{"en":"In America most leisure-time activities are about a million times better than anywhere else","cn":"美国大多数休闲娱乐活动比其他地方要丰富得多的多。"}},{"pos":"ADV-INDEF 不定副词","cn":"任何地方；到处","en":"You use anywhere to refer to a place when you are emphasizing that it could be any of a large number of places.","ex":{"en":"Rachel would have known Julia Stone anywhere.","cn":"甭管到哪儿，雷切尔都会认出朱莉娅·斯通。"}},{"pos":"ADV-INDEF 不定副词","cn":"（指某个范围内）任何一点上","en":"When you do not want to be exact, you use anywhere to refer to a particular range of things.","ex":{"en":"His shoes cost anywhere from $200 up","cn":"他买的鞋子总在200美元以上。"}},{"pos":"ADV-INDEF 不定副词","cn":"（用于强调）根本，一点儿，将近，几乎","en":"You use anywhere in expressions such as anywhere near and anywhere close to to emphasize a statement that you are making.","ex":{"en":"There weren't anywhere near enough empty boxes","cn":"空箱子数量远远不够。"}},{"pos":"PHRASE 短语","cn":"毫无进展;毫无成就","en":"If you say that someone or something is not getting anywhere or is not going anywhere, you mean that they are not making progress or achieving a satisfactory result.","ex":{"en":"The conversation did not seem to be getting anywhere","cn":"会谈好像没有取得任何进展。"}}]},"examples":[{"en":"Do you know anywhere I can buy a second-hand computer?","cn":"你知道我在哪儿可以买到二手计算机吗？"},{"en":"Many of these animals are not found anywhere else.","cn":"这些动物中有很多是其他地方没有的。"}]},"ankle":{"oxford":{"phon":"ˈæŋkl","pos":"noun","senses":[{"en":"the joint connecting the foot to the leg; the narrow part of the leg just above the ankle joint","cn":"踝；踝关节","ex":{"en":"to sprain/break/twist your ankle","cn":"扭伤／折断／扭了踝关节"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"踝；脚脖子","en":"Your ankle is the joint where your foot joins your leg.","ex":{"en":"John twisted his ankle badly.","cn":"约翰的脚脖子崴得很严重。"}}]},"media":{"uk":"media/uk/ankle__gb_1.mp3","us":"media/us/ankle__us_1.mp3"},"examples":[{"en":"My ankles have swollen.","cn":"我的两个脚腕子都肿了。"},{"en":"We found ourselves ankle-deep in water (= the water came up to our ankles).","cn":"水淹到了我们的脚踝。"}]},"anticipation":{"media":{"uk":"media/uk/anticipation__gb_1.mp3","us":"media/us/anticipation__us_1.mp3"},"oxford":{"phon":"ænˌtɪsɪˈpeɪʃn","pos":"noun","senses":[{"en":"the fact of seeing that something might happen in the future and perhaps doing something about it now","cn":"预料；预期；预见；预计","ex":{"en":"He bought extra food in anticipation of more people coming than he'd invited.","cn":"他预料来的客人会比邀请的多，就多买了食物。"}},{"en":"a feeling of excitement about something (usually something good) that is going to happen","cn":"期盼；期望","ex":{"en":"happy/eager/excited anticipation","cn":"愉快的／殷切的／激动的期盼"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"预期;预料;期望;期盼","en":"Anticipation is a feeling of excitement about something pleasant or exciting that you know is going to happen.","ex":{"en":"There's been an atmosphere of anticipation around here for a few days now","cn":"几天来这里一直有一种满怀期待的气氛。"}},{"pos":"PHRASE 短语","cn":"期待着；预计到","en":"If something is done in anticipation of an event, it is done because people believe that event is going to happen.","ex":{"en":"Troops in the Philippines have been put on full alert in anticipation of trouble during a planned general strike.","cn":"因料到在有组织的大罢工期间可能会出现骚乱，菲律宾的军队已进入全面戒备状态。"}}]},"examples":[{"en":"He bought extra food in anticipation of more people coming than he'd invited.","cn":"他预料来的客人会比邀请的多，就多买了食物。"},{"en":"The courtroom was filled with anticipation.","cn":"法庭上人们满怀期望的心情。"}]},"analysis":{"media":{"uk":"media/uk/analysis__gb_1.mp3","us":"media/us/analysis__us_1.mp3"},"oxford":{"phon":"əˈnæləsɪs","pos":"noun","senses":[{"en":"the detailed study or examination of something in order to understand more about it; the result of the study","cn":"（对事物的）分析，分析结果","g":"[uncountable, countable]","ex":{"en":"statistical/data analysis","cn":"统计／数据分析"}},{"en":"a careful examination of a substance in order to find out what it consists of","cn":"（对物质成分的）分析","g":"[uncountable, countable]","ex":{"en":"The blood samples are sent to the laboratory for analysis.","cn":"血样要送往实验室进行分析。"}},{"en":"a method of treating somebody who has problems with their mental health by asking them to talk about past experiences and feelings, and trying to help them understand fears and feelings that they were not conscious of","cn":"精神分析（疗法）；心理分析（疗法）","g":"[uncountable]","ex":{"en":"In analysis the individual resolves difficult emotional conflicts.","cn":"在精神分析疗法中，个人可以化解严重的情感冲突。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"细察；分析","en":"Analysis is the process of considering something carefully or using statistical methods in order to understand it or explain it.","ex":{"en":"Her criteria defy analysis","cn":"她的标准让人搞不明白。"}},{"pos":"N-VAR 可变名词","cn":"分析;分解","en":"Analysis is the scientific process of examining something in order to find out what it consists of.","ex":{"en":"They collect blood samples for analysis at a national laboratory","cn":"他们采集血样供一个国家实验室进行分析。"}},{"pos":"N-COUNT 可数名词","cn":"分析报告；分析结果","en":"An analysis is an explanation or description that results from considering something carefully.","ex":{"en":"...coming up after the newscast, an analysis of President Bush's domestic policy.","cn":"在新闻报道之后是对布什总统国内政策的解读"}},{"pos":"PHRASE 短语","cn":"归根结底；总之","en":"You use the expression in the final analysis or in the last analysis to indicate that the statement you are making is the most important or basic aspect of an issue.","ex":{"en":"I'm on the right track and I think in the final analysis people will understand that","cn":"我的思路对头，我认为最终人们会明白的。"}}]},"examples":[{"en":"In analysis the individual resolves difficult emotional conflicts.","cn":"在心理分析治疗法中，个人可以化解严重的情感冲突。"},{"en":"You can ask for a chemical analysis of your tap water.","cn":"你可以要求给你的自来水做化学分析。"}]},"analogies":{"oxford":{"phon":"əˈnælədʒi","pos":"noun","senses":[{"en":"a comparison of one thing with another thing that has similar features; a feature that is similar","cn":"类比；比拟；相似之处"},{"en":"the process of comparing one thing with another thing that has similar features in order to explain it","cn":"类推；比拟"}]},"media":{"uk":"media/uk/analogy__gb_1.mp3","us":"media/us/analogy__us_1.mp3"}},"annual":{"media":{"uk":"media/uk/annual__gb_1.mp3","us":"media/us/annual__us_1.mp3"},"oxford":{"phon":"ˈænjuəl","pos":"adjective","senses":[{"en":"happening or done once every year","cn":"每年的；一年一次的；年度的","ex":{"en":"an annual meeting/event/report/conference","cn":"年度会议／活动／报告／大会"}},{"en":"relating to a period of one year","cn":"一年的","ex":{"en":"an annual income/revenue/budget/fee/salary/turnover","cn":"年收入；年收益；年度预算；年费；年薪；年营业额"}},{"en":"a book, especially one for children, that is published once a year, with the same title each time, but different contents","cn":"年刊；年报；年鉴","ex":{"en":"The children usually asked for comic or sporting annuals for Christmas.","cn":"孩子们通常会要求圣诞节看漫画或体育年鉴。"},"pos":"noun"},{"en":"any plant that grows and dies within one year or season","cn":"一年生植物；一季生植物","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"一年一次的；每年的","en":"Annual events happen once every year.","ex":{"en":"...the annual conference of Britain's trade union movement","cn":"英国工会运动的年会"}},{"pos":"ADJ 形容词","cn":"年度的;全年的","en":"Annual quantities or rates relate to a period of one year.","ex":{"en":"Annual costs, tuition and fees, £6,600","cn":"每年的花销、学费和各项杂费6,600英镑。"}},{"pos":"N-COUNT 可数名词","cn":"年刊;年报;年鉴","en":"An annual is a book or magazine that is published once a year.","ex":{"en":"I looked for Wyman's picture in my high-school annual","cn":"我在中学年刊中寻找怀曼的照片。"}},{"pos":"N-COUNT 可数名词","cn":"一年生植物","en":"An annual is a plant that grows and dies within one year.","ex":{"en":"The simplest way to deal with these hardy annuals is to sow them where they are to flower.","cn":"处理这些一年生耐寒植物最简单的办法是将他们种在能开花的地方。"}}]},"examples":[{"en":"an average annual growth rate of 8%","cn":"平均 8% 的年增长率"},{"en":"an annual meeting/event/report","cn":"年会；一年一度的大事；年度报告"}]},"anonymously":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is anonymous does something without saying what their name is, or their name is not known","cn":""},{"en":"an unnamed person is someone whose name has not been made known publicly","cn":""}]},"examples":[{"en":"the anonymous author of a collection of poems","cn":"","src":"ld"},{"en":"the anonymous donor of a large sum of money","cn":"","src":"ld"}],"media":{"uk":"media/uk/anonymously__gb_1.mp3","us":"media/us/anonymously__us_1.mp3"},"oxford":{"phon":"əˈnɒnɪməsli","pos":"adverb","senses":[{"en":"by somebody who does not want their name to be known or made public","cn":"匿名的；不具名的","ex":{"en":"The house was donated anonymously to the Spanish Colonial Arts Society in 1998.","cn":"该房屋于 1998 年匿名捐赠给西班牙殖民艺术协会。"}}]}},"anchorwoman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指新闻节目的）电（视）台节目女主持人","en":"The anchorwoman on a television or radio programme, especially a news programme, is the woman who presents it."}]},"oxford":{"phon":"ˈæŋkəwʊmən","pos":"noun","senses":[{"en":"a woman who presents a live radio or television programme and introduces reports by other people","cn":"（电台、电视现场直播的）节目主持人"}]}},"anything":{"media":{"uk":"media/uk/anything__gb_1.mp3","us":"media/us/anything__us_1.mp3"},"oxford":{"phon":"ˈeniθɪŋ","pos":"pronoun","senses":[{"en":"used instead of something in negative sentences and in questions; after if/whether; and after verbs such as prevent, ban, avoid, etc.","cn":"（用于否定句、疑问句，也用于 if 或 whether 之后，或紧接 prevent、ban、avoid 等动词，代替 something）任何东西，任何事物","ex":{"en":"Would you like anything else?","cn":"你要点别的什么吗？"}},{"en":"any thing at all, when it does not matter which","cn":"随便哪个东西；随便什么事物","ex":{"en":"I'm so hungry, I'll eat anything.","cn":"我饿慌了，随便吃什么都行。"}},{"en":"any thing of importance","cn":"重要东西；重要事物","ex":{"en":"Is there anything (= any truth) in these rumours?","cn":"这些传闻中有没有真实的东西？"}}]},"collins":{"senses":[{"pos":"PRON-INDEF 不定代词","cn":"（用于否定句）任何事物，什么事情","en":"You use anything in statements with negative meaning to indicate in a general way that nothing is present or that an action or event does not or cannot happen.","ex":{"en":"We can't do anything","cn":"我们什么都做不了。"}},{"pos":"PRON-INDEF 不定代词","cn":"（用于疑问句或条件从句）任何事物，任何事情","en":"You use anything in questions and conditional clauses to ask or talk about whether something is present or happening.","ex":{"en":"What happened, is anything wrong?","cn":"怎么了，出什么事了吗？"}},{"pos":"PRON-INDEF 不定代词","cn":"（用于描述所谈论事物的词语前）…的东西，…的事情","en":"You can use anything before words which indicate the kind of thing you are talking about.","ex":{"en":"More than anything else, he wanted to become a teacher","cn":"他最想成为一名教师。"}},{"pos":"PRON-INDEF 不定代词","cn":"（用于加强语气）无论什么东西，随便什么事情","en":"You use anything to emphasize a possible thing, event, or situation, when you are saying that it could be any one of a very large number of things.","ex":{"en":"He is young, fresh, and ready for anything","cn":"他年轻又富有朝气，什么事都愿意做。"}},{"pos":"PRON-INDEF 不定代词","cn":"（用于强调）多少接近于","en":"You use anything in expressions such as anything near ,anything close to and anything like to emphasize a statement that you are making.","ex":{"en":"Doctors have decided the only way he can live anything near a normal life is to give him an operation","cn":"医生的结论是只有做手术，他才有可能过上基本正常的生活。"}},{"pos":"PRON-INDEF 不定代词","cn":"（限定范围内的）任何一点","en":"When you do not want to be exact, you use anything to talk about a particular range of things or quantities.","ex":{"en":"Factory farming has turned the cow into a milk machine, producing anything from 25 to 40 litres of milk per day","cn":"集约饲养把奶牛变成了生产牛奶的机器，每天差不多要挤出25升到40升的牛奶。"}},{"pos":"PHRASE 短语","cn":"（用于形容词后表示强调）非常，十分","en":"You use as anything after an adjective to emphasize a quality that someone has.","ex":{"en":"He used to be as smart as anything","cn":"他过去聪明绝顶。"}},{"pos":"PHRASE 短语","cn":"单单除…之外;根本不;远非","en":"You use anything but in expressions such as anything but quiet and anything but attractive to emphasize that something is not the case.","ex":{"en":"I will be anything but quiet on Saturday night!","cn":"星期六的晚上我根本静不下心来！"}},{"pos":"PHRASE 短语","cn":"决不","en":"You can say that you would not do something for anything to emphasize that you definitely would not want to do or be a particular thing.","ex":{"en":"I wouldn't want to move for anything in the world","cn":"就是天塌了我也不搬走。"}},{"pos":"PHRASE 短语","cn":"（尤用于否定句后，对所说之事进行补充说明）甚至正相反，甚至还不如说","en":"You use if anything, especially after a negative statement, to introduce a statement that adds to what you have just said.","ex":{"en":"I never had to clean up after him. If anything, he did most of the cleaning.","cn":"我从来不用跟在他后面打扫卫生。恰恰相反，他包揽了大部分的清洁工作。"}},{"pos":"PHRASE 短语","cn":"或其他什么的；诸如此类","en":"You can add or anything to the end of a clause or sentence in order to refer vaguely to other things that are or may be similar to what has just been mentioned.","ex":{"en":"Listen, if you talk to him or anything make sure you let us know, will you","cn":"听着，如果你和他说话或什么的，一定要让我们知道，好吗？"}}]},"examples":[{"en":"If you want to call a meeting or anything, just let me know.","cn":"要是你想召集个会议什么的，就请告诉我。"},{"en":"There's never anything worth watching on TV.","cn":"电视上根本没有什么值得看的节目。"}]},"anyone":{"media":{"uk":"media/uk/anyone__gb_1.mp3","us":"media/us/anyone__us_1.mp3"},"oxford":{"phon":"ˈeniwʌn","pos":"pronoun","senses":[{"en":"used instead of someone in negative sentences and in questions after if/whether, and after verbs such as prevent, forbid, avoid, etc.","cn":"（用于否定句、疑问句，也用于 if 或 whether 之后，或紧接 prevent、forbid、avoid 等动词，代替 someone）任何人","ex":{"en":"Is anyone there?","cn":"有人吗？"}},{"en":"any person at all; it does not matter who","cn":"随便哪个人","ex":{"en":"Anybody can see that it's wrong.","cn":"随便哪个人都可以看出这是错的。"}},{"en":"an important person","cn":"重要人物","ex":{"en":"She wasn't anyone before she got that job.","cn":"她在获得那个职位之前不过是个无名之辈。"}}]},"collins":{"senses":[{"pos":"PRON-INDEF 不定代词","cn":"（用于否定句）任何人","en":"You use anyone or anybody in statements with negative meaning to indicate in a general way that nobody is present or involved in an action.","ex":{"en":"I won't tell anyone I saw you here","cn":"我不会告诉任何人我在这儿见过你。"}},{"pos":"PRON-INDEF 不定代词","cn":"（用于疑问句或条件从句）任何人","en":"You use anyone or anybody in questions and conditional clauses to ask or talk about whether someone is present or doing something.","ex":{"en":"Why would anyone want that job?","cn":"为什么会有人想要那份工作呢？"}},{"pos":"PRON-INDEF 不定代词","cn":"（用于描述所谈论的人的词语前）…人","en":"You use anyone or anybody before words which indicate the kind of person you are talking about.","ex":{"en":"I always had been the person who achieved things before anyone else at my age","cn":"我过去总是比同龄人要捷足先登。"}},{"pos":"PRON-INDEF 不定代词","cn":"（用于强调）任何人，随便哪个人","en":"You use anyone or anybody to refer to a person when you are emphasizing that it could be any person out of a very large number of people.","ex":{"en":"Anyone could be doing what I'mdoing","cn":"我在做的事，谁都可能正在做。"}},{"pos":"PHRASE 短语","cn":"重要人物;有影响的人物","en":"You use anyone who is anyone and anybody who is anybody to refer to people who are important or influential.","ex":{"en":"It seems anyone who's anyone in business is going to the conference.","cn":"似乎商界所有重要人物都将参加那个会议。"}}]},"examples":[{"en":"She wasn't anyone before she got that job.","cn":"她在获得那个职位之前不过是个无名之辈。"},{"en":"Anybody can see that it's wrong.","cn":"随便哪个人都可以看出这是错的。"}]},"anyway":{"oxford":{"phon":"ˈeniweɪ","pos":"adverb","senses":[{"en":"used when adding something to support an idea or argument","cn":"而且；加之；反正","ex":{"en":"It's too expensive and anyway the colour doesn't suit you.","cn":"这个太贵，而且颜色也不适合你。"}},{"en":"despite something; even so","cn":"尽管；即使这样","ex":{"en":"It's going to happen anyway, so we won't object to it.","cn":"既然无论怎样都会发生，那我们就不反对了。"}},{"en":"used when changing the subject of a conversation, ending the conversation or returning to a subject","cn":"（转换话题、结束谈话或回到原话题时说）不过，总之，反正","ex":{"en":"So, anyway, back to what I was saying.","cn":"因此，总之，回到我刚谈的话题上来。"}},{"en":"used to correct or slightly change what you have said","cn":"（纠正或略微改变说过的话）至少","ex":{"en":"I think she's right. I hope so, anyway.","cn":"我认为她是对的。至少我希望如此。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"不管怎么说；无论如何","en":"You use anyway or anyhow to indicate that a statement explains or supports a previous point.","ex":{"en":"I'm certain David's told you his business troubles. Anyway, it's no secret that he owes money","cn":"我敢肯定戴维已经告诉过你他生意上有麻烦了。反正他欠钱也不是什么秘密了。"}},{"pos":"ADV 副词","cn":"尽管如此;不管怎样","en":"You use anyway or anyhow to suggest that a statement is true or relevant in spite of other things that have been said.","ex":{"en":"I don't know why I settled on Aberdeen, but anyway I did","cn":"我不知道为什么我定居在阿伯丁，尽管如此，我还是这么做了。"}},{"pos":"ADV 副词","cn":"至少","en":"You use anyway or anyhow to correct or modify a statement, for example to limit it to what you definitely know to be true.","ex":{"en":"Mary Ann doesn't want to have children. Not right now, anyway.","cn":"玛丽·安不想要孩子，至少现在不想。"}},{"pos":"ADV 副词","cn":"到底；究竟","en":"You use anyway or anyhow to indicate that you are asking what the real situation is or what the real reason for something is.","ex":{"en":"What do you want from me, anyway?","cn":"你到底想从我这儿得到什么？"}},{"pos":"ADV 副词","cn":"（表示略去一些细节转到下一个主要话题）总之","en":"You use anyway or anyhow to indicate that you are missing out some details in a story and are passing on to the next main point or event.","ex":{"en":"I was told to go to Reading for this interview. It was a very amusing affair. Anyhow, I got the job.","cn":"我被通知前往雷丁面试。整个过程很有意思。总之，我被录用了。"}},{"pos":"ADV 副词","cn":"（用于转移话题或回到原话题）对了，好吧","en":"You use anyway or anyhow to change the topic or return to a previous topic.","ex":{"en":"'I've got a terrible cold.' — 'Have you? Oh dear. Anyway, so you're not going to go away this weekend?'","cn":"“我得了重感冒。”——“是吗？哦，天啊。对了，那你这个周末就不走了吧？”"}},{"pos":"ADV 副词","cn":"（表示有意结束谈话）那么","en":"You use anyway or anyhow to indicate that you want to end the conversation.","ex":{"en":"'Anyway, I'd better let you have your dinner. Give our love to Francis. Bye.'","cn":"“那么，我不打扰你用餐了。代我们向弗朗西斯问好。再见。”"}}]},"media":{"uk":"media/uk/anyway__gb_1.mp3","us":"media/us/anyway__us_1.mp3"},"examples":[{"en":"She works in a bank. She did when I last saw her, anyway.","cn":"她在银行工作。至少我上次见到她时是这样。"},{"en":"I'm afraid we can't come, but thanks for the invitation anyway.","cn":"恐怕我们来不了，不过还是感谢邀请。"}]},"angel":{"oxford":{"phon":"ˈeɪndʒl","pos":"noun","senses":[{"en":"a spirit who is believed to be a servant of God, and is sent by God to deliver a message or perform a task. Angels are often shown dressed in white, with wings.","cn":"天使","ex":{"en":"a host of angels","cn":"一群天使"}},{"en":"a person who is very good and kind; a child who behaves well","cn":"安琪儿（指善良的人或乖巧的小孩）；善人","ex":{"en":"John is no angel, believe me (= he does not behave well).","cn":"相信我，约翰绝非善良之辈。"}},{"en":"used when you are talking to somebody and you are grateful to them","cn":"大好人（感激某人时所说）","lab":"informal","ex":{"en":"Thanks Dad, you're an angel.","cn":"谢谢爸爸，你是个大好人。"}},{"en":"a person who supports a business by investing money in it, especially somebody who supports a new small business with their own money","cn":"天使投资人（尤指新创小企业的投资者）","ex":{"en":"When will the angels get their money back?","cn":"天使们什么时候才能拿回钱呢？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"天使","en":"Angels are spiritual beings that some people believe are God's servants in heaven."},{"pos":"N-COUNT 可数名词","cn":"（尤用于得到友好对待或帮助时）大好人，大善人","en":"You can call someone you like very much an angel in order to show affection, especially when they have been kind to you or done you a favour.","ex":{"en":"Thank you a thousand times, you're an angel.","cn":"万分感谢，你真是个大好人。"}},{"pos":"N-COUNT 可数名词","cn":"安琪儿;天使;善人","en":"If you describe someone as an angel, you mean that they seem to be very kind and good.","ex":{"en":"Poppa thought her an angel","cn":"爸爸视她为小天使。"}},{"pos":"PHRASE 短语","cn":"行善；在道义一方","en":"If you say that someone is on the side of the angels, you believe very strongly that what they are doing is right.","ex":{"en":"Billy is on the side of the angels when it comes to racial tolerance.","cn":"说起种族间的包容，比利可真是宅心仁厚。"}},{"pos":"PHRASE 短语","cn":"愚蠢地冒险;鲁莽行事;暴虎冯河","en":"If you say that someone rushes in where angels fear to tread, you are criticizing them gently because they get themselves into dangerous or difficult situations without thinking carefully enough about what they are doing.","ex":{"en":"Martin is inclined to rush in where angels fear to tread.","cn":"马丁总是喜欢贸然行事。"}}]},"media":{"uk":"media/uk/angel__gb_1.mp3","us":"media/us/angel__us_1.mp3"},"examples":[{"en":"John is no angel , believe me (= he does not behave well).","cn":"相信我，约翰绝非善良之辈。"},{"en":"Thanks Dad, you're an angel.","cn":"谢谢爸爸，你是个大好人。"}]},"annoying":{"media":{"uk":"media/uk/annoying__gb_1.mp3","us":"media/us/annoying__us_1.mp3"},"oxford":{"phon":"əˈnɔɪɪŋ","pos":"adjective","senses":[{"en":"making somebody feel slightly angry","cn":"使恼怒的；使生气的；使烦恼的","ex":{"en":"This interruption is very annoying.","cn":"这样打岔令人讨厌。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人生气的；令人厌烦的","en":"Someone or something that is annoying makes you feel fairly angry and impatient.","ex":{"en":"You must have found my attitude annoying","cn":"你肯定觉得我的态度讨人厌。"}}]},"examples":[{"en":"Her most annoying habit was eating with her mouth open.","cn":"她最让人讨厌的习惯就是张着嘴吃东西。"},{"en":"This interruption is very annoying.","cn":"这样打岔令人讨厌。"}]},"anxiety":{"media":{"uk":"media/uk/anxiety__gb_1.mp3","us":"media/us/anxiety__us_1.mp3"},"oxford":{"phon":"æŋˈzaɪəti","pos":"noun","senses":[{"en":"the state of feeling nervous or worried that something bad is going to happen","cn":"焦虑；忧虑","g":"[uncountable]","ex":{"en":"acute/intense/deep anxiety","cn":"非常／极度／深深的忧虑"}},{"en":"a mental illness that causes somebody to worry so much that it has a very negative effect on their daily life","cn":"焦虑症","g":"[uncountable]","lab":"psychology","ex":{"en":"Some people are feeling the pressure and suffering from anxiety and depression.","cn":"有的人感到有压力，患上焦虑和抑郁。"}},{"en":"a worry or fear about something","cn":"担心；忧虑；害怕","g":"[countable]","ex":{"en":"If you're worried about your health, share your anxieties with your doctor.","cn":"你要是担心自己的健康，就把忧虑告诉医生吧。"}},{"en":"a strong feeling of wanting to do something or of wanting something to happen","cn":"渴望","g":"[uncountable]","ex":{"en":"the candidate’s anxiety to win the vote","cn":"候选人对选举胜利的渴望"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"忧虑；焦虑；不安","en":"Anxiety is a feeling of nervousness or worry.","ex":{"en":"Her voice was full of anxiety","cn":"她的声音满是焦虑不安。"}}]},"examples":[{"en":"If you're worried about your health, share your anxieties with your doctor.","cn":"你要是担心自己的健康，就把忧虑告诉医生吧。"},{"en":"Some hospital patients experience high levels of anxiety.","cn":"有些住院病人十分焦虑不安。"}]},"anger":{"media":{"uk":"media/uk/anger__gb_1.mp3","us":"media/us/anger__us_1.mp3"},"oxford":{"phon":"ˈæŋɡə(r)","pos":"noun","senses":[{"en":"the strong feeling that you have when something has happened that you think is bad and unfair","cn":"怒；怒火；怒气","ex":{"en":"She had to find a way to express her pent-up anger.","cn":"她必须得找个办法发泄她压抑的怒火。"}},{"en":"to make somebody angry","cn":"激怒某人","ex":{"en":"The question clearly angered him.","cn":"这个问题显然激怒了他。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"怒；愤怒","en":"Anger is the strong emotion that you feel when you think that someone has behaved in an unfair, cruel, or unacceptable way.","ex":{"en":"He cried with anger and frustration","cn":"他愤怒而又沮丧得哭了起来。"}},{"pos":"VERB 动词","cn":"使发怒；使生气；激怒","en":"If something angers you, it makes you feel angry.","ex":{"en":"The decision to allow more offshore oil drilling angered some Californians.","cn":"允许进行更多近海石油钻探的决定激怒了一些加利福尼亚人。"}}]},"examples":[{"en":"the growing anger and frustration of young unemployed people","cn":"年轻失业者日益增长的愤怒和沮丧"},{"en":"He was filled with anger at the way he had been treated.","cn":"他因遭受如此待遇而怒火满腔。"}]},"ankles":{"oxford":{"phon":"ˈæŋkl","pos":"noun","senses":[{"en":"the joint connecting the foot to the leg","cn":"踝；踝关节"}]}},"analogy":{"media":{"uk":"media/uk/analogy__gb_1.mp3","us":"media/us/analogy__us_1.mp3"},"oxford":{"phon":"əˈnælədʒi","pos":"noun","senses":[{"en":"a comparison of one thing with another thing that has similar features; a feature that is similar","cn":"类比；比拟；相似之处","g":"[countable]","ex":{"en":"The teacher drew an analogy between the human heart and a pump.","cn":"老师打了个比喻，把人的心脏比作水泵。"}},{"en":"the process of comparing one thing with another thing that has similar features in order to explain it","cn":"类推；比拟","g":"[uncountable]","ex":{"en":"learning by analogy","cn":"用类推法学习"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"相似；类似；类推；类比","en":"If you make or draw an analogy between two things, you show that they are similar in some way.","ex":{"en":"It is probably easier to make an analogy between the courses of the planets, and two trains travelling in the same direction.","cn":"将行星的运行比作两列火车朝同一方向行驶可能更容易些。"}}]},"examples":[{"en":"There are no analogies with any previous legal cases.","cn":"以往的法律案件没有哪一宗可与此案类比。"},{"en":"The teacher drew an analogy between the human heart and a pump.","cn":"老师打了个比喻，把人的心脏比作水泵。"}]},"angeles":{"oxford":{"phon":"ˈeɪndʒl","pos":"noun","senses":[{"en":"a spirit who is believed to be a servant of God, and is sent by God to deliver a message or perform a task. Angels are often shown dressed in white, with wings.","cn":"天使"},{"en":"a person who is very good and kind; a child who behaves well","cn":"安琪儿（指善良的人或可爱的小孩）；善人"}]},"media":{"uk":"media/uk/angel__gb_1.mp3","us":"media/us/angel__us_1.mp3"}},"anomalous":{"oxford":{"phon":"əˈnɒmələs","pos":"adjective","senses":[{"en":"different from what is normal or expected","cn":"异常的；反常的","ex":{"en":"He is in an anomalous position as the only part-time worker in the firm.","cn":"他与众不同，是公司里唯一的兼职人员。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"反常的；异常的；例外的","en":"Something that is anomalous is different from what is usual or expected.","ex":{"en":"For years this anomalous behaviour has baffled scientists","cn":"几年来这种反常行为让科学家们很困惑。"}}]},"media":{"uk":"media/uk/anomalous__gb_1.mp3","us":"media/us/anomalous__us_1.mp3"},"examples":[{"en":"a highly anomalous situation","cn":"极其反常的形势"},{"en":"anomalous results","cn":"异常的结果"}]},"anecdotal":{"oxford":{"phon":"ˌænɪkˈdəʊtl","pos":"adjective","senses":[{"en":"possibly not true or accurate because it is based on personal accounts rather than facts or research","cn":"传闻的；轶事的","ex":{"en":"Anecdotal evidence suggests there were irregularities at the polling station on the day of the election.","cn":"传闻证据表明，选举当天投票站存在违规行为。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"传闻的；轶事的","en":"Anecdotal evidence is based on individual accounts, rather than on reliable research or statistics, and so may not be valid.","ex":{"en":"Anecdotal evidence suggests that sales in Europe have slipped.","cn":"传闻有证据表明欧洲的销售量已经下滑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（讲演或写作）含轶事的，多轶闻的","en":"Anecdotal speech or writing is full of anecdotes or is based on anecdotes.","ex":{"en":"Gray's book is anecdotal and entertaining.","cn":"格雷的书中尽是些八卦消息，颇具娱乐性。"}}]},"media":{"uk":"media/uk/anecdotal__gb_1.mp3","us":"media/us/anecdotal__us_1.mp3"},"examples":[{"en":"This reaction has been reported anecdotally by a number of patients.","cn":"一些患者据称有这种反应。"},{"en":"anecdotal evidence","cn":"传闻的证据"}]},"anchor":{"media":{"img":["media/ldoce/img/anchor.jpg","media/pic/anchor.jpg"],"uk":"media/uk/anchor__gb_1.mp3","us":"media/us/anchor__us_1.mp3"},"oxford":{"phon":"ˈæŋkə(r)","pos":"noun","senses":[{"en":"a heavy metal object that is attached to a rope or chain and dropped over the side of a ship or boat to keep it in one place","cn":"锚","ex":{"en":"to drop anchor","cn":"抛锚"}},{"en":"a person or thing that gives somebody a feeling of safety","cn":"给以安全感的人（或物）；精神支柱；顶梁柱","ex":{"en":"the anchor of the family","cn":"全家的顶梁柱"}},{"en":"a person who presents a live radio or television programme and introduces reports by other people; an anchorman or anchorwoman","cn":"（广播电视直播节目的）主持人；播音员","ex":{"en":"She was questioned by an NBC anchor about her trip.","cn":"全国广播公司（NBC）主播询问了她的旅行情况。"}},{"en":"to let an anchor down from a boat or ship in order to prevent it from moving away","cn":"抛锚；下锚","g":"[intransitive, transitive]","ex":{"en":"We anchored off the coast of Spain.","cn":"我们在西班牙沿海抛锚停泊。"},"pos":"verb"},{"en":"to fix something in position so that it cannot move","cn":"使固定；扣牢；系牢","g":"[transitive, often passive]","ex":{"en":"Make sure the table is securely anchored.","cn":"务必要把桌子固定好。"},"pos":"verb"},{"en":"to base something on something else","cn":"使扎根；使基于","g":"[transitive, usually passive]","ex":{"en":"Her novels are anchored in everyday experience.","cn":"她的小说取材自日常生活经验。"},"pos":"verb"},{"en":"to be the person who introduces reports or reads the news on television or radio","cn":"主持（电视、广播节目）","g":"[intransitive, transitive]","lab":"especially North American English","ex":{"en":"She anchored the evening news for seven years.","cn":"她主持了七年晚间新闻报道。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"锚","en":"An anchor is a heavy hooked object that is dropped from a boat into the water at the end of a chain in order to make the boat stay in one place."},{"pos":"V-ERG 及物/不及物动词","cn":"抛锚；使停泊","en":"When a boat anchors or when you anchor it, its anchor is dropped into the water in order to make it stay in one place.","ex":{"en":"We could anchor off the pier","cn":"我们可以在码头附近下锚停泊。"}},{"pos":"VERB 动词","cn":"把…系住；使稳住；使固定","en":"If you anchor an object somewhere, you fix it to something to prevent it moving from that place.","ex":{"en":"The roots anchor the plant in the earth","cn":"根部使植物固定在土壤中。"}},{"pos":"N-COUNT 可数名词","cn":"固定桩；系缚物；支柱；靠山","en":"If one thing is the anchor for something else, it makes that thing stable and secure.","ex":{"en":"He provided an emotional anchor for her","cn":"他是她的精神支柱。"}},{"pos":"VERB 动词","cn":"与…有紧密联系;使扎根;使固守","en":"If something is anchored in something or to something, it has strong links with it.","ex":{"en":"A united Germany must be firmly anchored in NATO if Europe is to remain stable","cn":"欧洲要保持稳定，德国必须统一并固守北约。"}},{"pos":"VERB 动词","cn":"主持（电视或电台节目，尤指新闻节目）","en":"The person who anchors a television or radio programme, especially a news programme, is the person who presents it and acts as a link between interviews and reports which come from other places or studios.","ex":{"en":"Viewers saw him anchoring a five-minute summary of regional news.","cn":"观众看见他主持一个5分钟的地方新闻摘要节目。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指新闻节目的）电（视）台节目主持人","en":"The anchor on a television or radio programme, especially a news programme, is the person who presents it.","ex":{"en":"He worked in the news division of ABC — he was the anchor of its 15-minute evening newscast.","cn":"他在美国广播公司的新闻部工作——他是晚间15分钟新闻播报的主持人。"}},{"pos":"PHRASE 短语","cn":"（船）抛着锚，停泊着","en":"If a boat is at anchor, it is floating in a particular place and is prevented from moving by its anchor.","ex":{"en":"Sailing boats lay at anchor in the narrow waterway.","cn":"帆船停泊在狭窄的水道上。"}},{"pos":"PHRASE 短语","cn":"抛锚;下锚","en":"When the people on a boat drop anchor or cast anchor, they drop the boat's anchor into the water in order to prevent the boat from moving.","ex":{"en":"We dropped anchor in a sheltered spot.","cn":"我们在一个能够遮风挡雨的地方下了锚。"}},{"pos":"PHRASE 短语","cn":"起锚；启航","en":"When the people on a boat weigh anchor or up anchor, they pull the anchor of the boat out of the water so that they can sail away."}]},"examples":[{"en":"The ship lay at anchor two miles off the rocky coast.","cn":"船在离岩岸两英里处抛锚停泊。"},{"en":"Her novels are anchored in everyday experience.","cn":"她的小说取材自日常生活经验。"}]},"anthropologists":{"oxford":{"phon":"ˌænθrəˈpɒlədʒɪst","pos":"noun","senses":[{"en":"a person who studies anthropology","cn":"人类学家"}]},"media":{"uk":"media/uk/anthropologist__gb_1.mp3","us":"media/us/anthropologist__us_1.mp3"}},"ancestors":{"oxford":{"phon":"ˈænsestə(r)","pos":"noun","senses":[{"en":"a person in your family who lived a long time ago","cn":"祖宗；祖先"},{"en":"an animal that lived in the past which a modern animal has developed from （","cn":"动物的）原种"}]}},"anymore":{"oxford":{"phon":"","pos":"adv.","senses":[{"en":"often used at the end of negative sentences and at the end of questions, to mean ‘any longer’ （","cn":"常用于否定句和疑问句末）再也（不），（不）再"},{"en":"Do not use ‘no more’ with this meaning.","cn":"不能用 no more 表示此义："}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（不）再;再也（不）","en":"If something does not happen or is not true anymore, it has stopped happening or is no longer true.","ex":{"en":"I don't ride my motorbike much anymore","cn":"我不怎么骑我的摩托车了。"}}]},"media":{"uk":"media/ldoce/hwd/bre/d/anymore0205.mp3","us":"media/ldoce/hwd/ame/c/anymore.mp3"},"examples":[{"en":"Nick doesn’t live here anymore.","cn":"尼克不再住在这里了。"},{"en":"I don't really like her anymore.","cn":"我不太喜欢她了。"}]},"analysts":{"oxford":{"phon":"ˈænəlɪst","pos":"noun","senses":[{"en":"a person whose job involves examining facts or materials in order to give an opinion on them","cn":"分析者；化验员"}]}},"anchors":{"oxford":{"phon":"ˈæŋkə(r)","pos":"noun","senses":[{"en":"a heavy metal object that is attached to a rope or chain and dropped over the side of a ship or boat to keep it in one place","cn":"锚"},{"en":"a person or thing that gives sb a feeling of safety","cn":"给以安全感的人（或物）；精神支柱；顶梁柱"}]}},"answered":{"oxford":{"phon":"ˈɑːnsə(r)","pos":"noun","senses":[{"en":"something that you say, write or do to react to a question or situation","cn":"答复；回答"},{"en":"something that you write or say in reply to a question in a test, an exam, an exercise, etc; the correct reply to a question in a test, etc. （","cn":"试题、练习等的）答案，正确答案"}]}},"answers":{"oxford":{"phon":"ˈɑːnsə(r)","pos":"noun","senses":[{"en":"something that you say, write or do to react to a question or situation","cn":"答复；回答"},{"en":"something that you write or say in reply to a question in a test, an exam, an exercise, etc; the correct reply to a question in a test, etc. （","cn":"试题、练习等的）答案，正确答案"}]}},"anticipating":{"oxford":{"phon":"ænˈtɪsɪpeɪt","pos":"verb","senses":[{"en":"to expect sth","cn":"预料；预期"},{"en":"to see what might happen in the future and take action to prepare for it","cn":"预见，预计（并做准备）"}]}},"announced":{"oxford":{"phon":"əˈnaʊns","pos":"verb","senses":[{"en":"to tell people sth officially, especially about a decision, plans, etc.","cn":"宣布，宣告（决定、计划等）"},{"en":"You cannot ‘announce somebody something’.","cn":"不能说 announce somebody something："}]}},"animals":{"oxford":{"phon":"ˈænɪml","pos":"noun","senses":[{"en":"a creature that is not a bird, a fish, a reptile , an insect or a human","cn":"兽；牲畜；动物（不包括鸟、鱼、爬行动物、昆虫和人）"},{"en":"any living thing that is not a plant or a human","cn":"动物（不包括植物或人的生物）"}]}},"anecdotes":{"oxford":{"phon":"ˈænɪkdəʊt","pos":"noun","senses":[{"en":"a short, interesting or amusing story about a real person or event","cn":"佚事；趣闻"},{"en":"a personal account of an event","cn":"传闻"}]}},"answering":{"oxford":{"phon":"ˈɑːnsə(r)","pos":"noun","senses":[{"en":"something that you say, write or do to react to a question or situation","cn":"答复；回答"},{"en":"something that you write or say in reply to a question in a test, an exam, an exercise, etc; the correct reply to a question in a test, etc. （","cn":"试题、练习等的）答案，正确答案"}]}},"annoys":{"oxford":{"phon":"əˈnɔɪ","pos":"verb","senses":[{"en":"to make sb slightly angry","cn":"使恼怒；使生气"},{"en":"to make sb uncomfortable or unable to relax","cn":"打扰；骚扰"}]}},"analyse":{"collins":{"senses":[{"pos":"VERB 动词","cn":"细察；分析","en":"If you analyse something, you consider it carefully or use statistical methods in order to fully understand it.","ex":{"en":"McCarthy was asked to analyse the data from the first phase of trials of the vaccine","cn":"麦卡锡被要求对第一阶段疫苗试验的数据作出分析。"}},{"pos":"VERB 动词","cn":"分析；分解；化验","en":"If you analyse something, you examine it using scientific methods in order to find out what it consists of.","ex":{"en":"We haven't had time to analyse those samples yet","cn":"我们还没有时间分析那些样本。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to look at something carefully and thoroughly because you want to find out more about it","cn":""},{"en":"to quickly examine something to find out what is wrong with it or to find out more about it. Have a look at is less formal than examine , and is the usual phrase to use in everyday English","cn":""},{"en":"to examine something carefully to make sure that it is correct, safe, or working properly, especially when it is your job to do this","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"To analyse ( analyze is U.S. English) something is to consider it in detail so you can figure out its workings or meaning."}]},"collocations":{"phrases":["ADV. carefully, critically, fully, in depth/detail, painstakingly, scientifically, systematically The results must be analysed in detail.","VERB + ANALYSE attempt to, try to | be difficult to, be impossible to The precise reasons for the disaster are difficult to analyse. | be po"]},"media":{"uk":"media/ldoce/hwd/bre/6/analyse0205.mp3","us":"media/ldoce/hwd/ame/c/laadanalyse.mp3"},"examples":[{"en":"The job involves gathering and analysing data.","cn":"这项工作包括搜集和分析资料。"},{"en":"We need to analyse what went wrong.","cn":"我们需要分析是什么出了差错。"}],"oxford":{"phon":"ˈænəlaɪz","pos":"verb","senses":[{"en":"to examine the nature or structure of something, especially by separating it into its parts, in order to understand or explain it","cn":"分析","ex":{"en":"The job involves collecting and analysing data.","cn":"这项工作包括收集和分析数据。"}},{"en":"to treat or study somebody using psychoanalysis","cn":"对…进行精神分析（或治疗）；对…做心理分析（或治疗）","lab":"both British English"}]}},"antiquity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"古代，古时（尤指古埃及、古希腊、古罗马时期）","en":"Antiquity is the distant past, especially the time of the ancient Egyptians, Greeks, and Romans.","ex":{"en":"...famous monuments of classical antiquity","cn":"古典时期的著名纪念碑"}},{"pos":"N-COUNT 可数名词","cn":"古迹;古建筑;古物","en":"Antiquities are things such as buildings, statues, or coins that were made in ancient times and have survived to the present day.","ex":{"en":"...collectors of Roman antiquities.","cn":"古罗马时期物品的收藏家"}},{"pos":"N-UNCOUNT 不可数名词","cn":"古老；年代悠久","en":"The antiquity of something is its great age.","ex":{"en":"...a town of great antiquity","cn":"历史悠久的小镇"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"ancient times","cn":"古代"},{"en":"the state of being very old","cn":"古老﹐年代久远"},{"en":"a building or object made in ancient times","cn":"古迹﹐古物﹐古建筑"}]},"vocab":{"pos":"n","senses":[{"en":"If you find an antiquity , call a museum: you just found something very old. Antiquity can also mean the idea of oldness."}]},"collocations":{"phrases":["ADJ. classical, Greek, Roman, etc. legends from Greek antiquity | late | immemorial, remote","VERB + ANTIQUITY date from, survive from | be lost in The origins of this ancient structure are lost in antiquity.","PREP. from ~ a study of urban life from antiquity to the present day | in ~ vases that were manufactured in late classical antiquity 2 a wor","ADJ. classical, Egyptian, Greek, Roman, etc.","VERB + ANTIQUITY collect He collects Egyptian and Roman antiquities. 3 great age","ADJ. considerable, great the considerable antiquity of the rocks in this region"]},"media":{"uk":"media/ldoce/hwd/bre/9/antiquity0205.mp3","us":"media/ldoce/hwd/ame/b/antiquity.mp3"},"examples":[{"en":"The statue was brought to Rome in antiquity.","cn":"这座雕像是古时运到罗马的。"},{"en":"A number of the monuments are of considerable antiquity.","cn":"有些历史遗迹相当古老。"}],"oxford":{"phon":"ænˈtɪkwəti","pos":"noun","senses":[{"en":"the ancient past, especially the times of the Greeks and Romans","cn":"古代（尤指古希腊和古罗马时期）","g":"[uncountable]","ex":{"en":"The statue was brought to Rome in antiquity.","cn":"这座雕像是古时运到罗马的。"}},{"en":"the state of being very old or ancient","cn":"古老；古","g":"[uncountable]","ex":{"en":"A number of the monuments are of considerable antiquity.","cn":"有些历史遗迹相当古老。"}},{"en":"an object from ancient times","cn":"文物；古物；古董；古迹","g":"[countable, usually plural]","ex":{"en":"Egyptian/Roman antiquities","cn":"埃及／罗马古物"}}]}},"anniversary":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"周年纪念（日）","en":"An anniversary is a date which is remembered or celebrated because a special event happened on that date in a previous year.","ex":{"en":"...the one hundredth anniversary of the birth of Ho Chi Minh.","cn":"胡志明诞辰一百周年纪念"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a date on which something special or important happened in a previous year","cn":"周年纪念（日）"}]},"vocab":{"pos":"n","senses":[{"en":"An anniversary marks the date on which an event happened — a five-year wedding anniversary occurs exactly five years after a wedding."}]},"collocations":{"phrases":["ADJ. first, second, etc.","VERB + ANNIVERSARY celebrate, commemorate, mark They held celebrations to mark the anniversary of Mozart's death.","ANNIVERSARY + VERB be, fall The anniversary of the founding of the charity falls on 12th November.","PREP. on an/the ~ on the 20th anniversary of his death 2 of a wedding","ADJ. first, second, etc. | wedding","VERB + ANNIVERSARY celebrate","PREP. on sb's ~ He bought her a diamond ring on their tenth wedding anniversary.","PHRASES a diamond, golden, silver, etc. wedding anniversary"]},"media":{"uk":"media/ldoce/hwd/bre/3/anniversary0205.mp3","us":"media/ldoce/hwd/ame/0/anniversary.mp3"},"examples":[{"en":"on the anniversary of his wife's death","cn":"在他妻子去世的周年忌日"},{"en":"the theatre's 25th anniversary celebrations","cn":"剧院 25 周年庆祝活动"}],"oxford":{"phon":"ˌænɪˈvɜːsəri","pos":"noun","senses":[{"en":"a date that is an exact number of years after the date of an important or special event","cn":"周年纪念日","lab":"especially North American English","ex":{"en":"on the anniversary of his wife’s death","cn":"在他妻子的忌日"}}]}},"annoyance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"气恼；烦恼","en":"Annoyance is the feeling that you get when someone makes you feel fairly angry or impatient.","ex":{"en":"To her annoyance the stranger did not go away","cn":"让她恼火的是，那个陌生人并没有走。"}},{"pos":"N-COUNT 可数名词","cn":"令人烦恼的事物；令人厌烦的事物","en":"An annoyance is something that makes you feel angry or impatient.","ex":{"en":"Inconsiderate neighbours can be more than an annoyance.","cn":"不为他人着想的邻居会非常惹人厌。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong emotion that you feel because someone has behaved badly or because a situation seems bad or unfair","cn":""},{"en":"slight anger or impatience","cn":""},{"en":"a feeling of being annoyed and impatient, especially because something keeps happening or someone keeps saying something","cn":""}]},"collocations":{"phrases":["ADJ. deep, great, intense A look of deep annoyance crossed his face. | obvious She tapped the table with her pen in obvious annoyance.","QUANT. flicker A flicker of annoyance crossed his face. | surge He felt a violent surge of annoyance.","VERB + ANNOYANCE cause He had been causing annoyance to the other guests. | feel I felt some annoyance when he told me his plans. | express,","PREP. in ~ He shook his head in annoyance. | with ~ Her cheeks flushed with annoyance. | ~ at/over, ~ with her annoyance with him over his f","PHRASES a look of annoyance There was a look of annoyance on his face. | a source of annoyance A dog that barks constantly can be a source o","ADJ. minor, petty A leaking roof is just one of life's petty annoyances!"]},"media":{"uk":"media/ldoce/hwd/bre/1/annoyance0205.mp3","us":"media/ldoce/hwd/ame/2/annoyance.mp3"},"examples":[{"en":"Much to our annoyance , they decided not to come after all.","cn":"他们终于决定不来，使我们很生气。"},{"en":"He could not conceal his annoyance at being interrupted.","cn":"他因受扰而难掩怒色。"}],"oxford":{"phon":"əˈnɔɪəns","pos":"noun","senses":[{"en":"the feeling of being slightly angry","cn":"恼怒；生气；烦恼","g":"[uncountable]","ex":{"en":"He could not conceal his annoyance at being interrupted.","cn":"他因受扰而难掩怒色。"}},{"en":"something that makes you slightly angry","cn":"使人烦恼的事；令人生气的事物","g":"[countable]","ex":{"en":"The delay is now shorter but still an annoyance.","cn":"延迟的时间现在变短了，但还是让人厌烦。"}}]}},"antithesis":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"对立面；形成对立（或对照）的事物","en":"The antithesis of something is its exact opposite.","ex":{"en":"The little black dress is the anithesis of fussy dressing.","cn":"与花哨的打扮形成鲜明对比的是这件小黑裙子。"}},{"pos":"N-COUNT 可数名词","cn":"（二者间的）对比，对照","en":"If there is an antithesis between two things, there is a contrast between them.","ex":{"en":"...the antithesis between instinct and reason.","cn":"本能和理智的对立"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"as different as possible from something else","cn":""},{"en":"if two people or things are opposites , they are as different as possible from each other","cn":""},{"en":"opposite to what is usual or to what has just been stated","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An antithesis is the complete opposite of something. Though the counterculture was strong in America in 1968, voters elected Richard Nixon, the antithesis of a hippie."}]},"collocations":{"phrases":["ADJ. complete, exact, very | sharp","VERB + ANTITHESIS be, represent","PREP. ~ between the sharp antithesis between their views | ~ of The company represented the antithesis of everything he admired."]},"media":{"uk":"media/ldoce/hwd/bre/a/antithesis0205.mp3","us":"media/ldoce/hwd/ame/7/antithesis.mp3"},"examples":[{"en":"There is an antithesis between the needs of the state and the needs of the people.","cn":"政府的需要和人民的需要这二者出现了对立。"},{"en":"Students finishing their education at 16 is the very antithesis of what society needs. * 16","cn":"岁停止学业的学生并非社会所需要的。"}],"oxford":{"phon":"ænˈtɪθəsɪs","pos":"noun","senses":[{"en":"the opposite of something","cn":"对立（面）；对照","ex":{"en":"Love is the antithesis of selfishness.","cn":"爱是自私的对立面。"}},{"en":"a contrast between two things","cn":"（二者间的）对比，对照","ex":{"en":"There is an antithesis between the needs of the state and the needs of the people.","cn":"政府的需要和人民的需要这二者存在着对立。"}}]}},"antagonism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"敌对；对立；对抗","en":"Antagonism between people is hatred or dislike between them. Antagonisms are instances of this.","ex":{"en":"There is still much antagonism between trades unions and the oil companies","cn":"工会和石油公司之间仍然存在着相当大的敌意。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"strong disagreement with or protest against something","cn":""},{"en":"a reason you give for opposing an idea or plan","cn":""},{"en":"a strong feeling of opposition to something, or dislike for someone, which is shown in your behaviour, and has often existed for a long time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Antagonism means hostility. You might feel antagonism to the teacher who gave you a D on your last test, and she might be angry at you for not working harder––there's antagonism between you."}]},"collocations":{"phrases":["ADJ. great, strong | mutual | class, personal, racial","VERB + ANTAGONISM feel, have She felt nothing but antagonism towards her boss. He seems to have an antagonism to the local people. | express","PREP. ~ between the antagonism between the two brothers | ~ to/towards her antagonism towards her mother"]},"media":{"uk":"media/ldoce/hwd/bre/d/antagonism0205.mp3","us":"media/ldoce/hwd/ame/2/antagonism.mp3"},"examples":[{"en":"The antagonism he felt towards his old enemy was still very strong.","cn":"他对宿敌的仇恨仍然十分强烈。"},{"en":"the racial antagonisms in society","cn":"社会上的种族对立情绪"}],"oxford":{"phon":"ænˈtæɡənɪzəm","pos":"noun","senses":[{"en":"feelings of opposition and hate","cn":"敌对；敌意；仇恨","ex":{"en":"The antagonism he felt towards his old enemy was still very strong.","cn":"他对宿敌的仇恨仍然十分强烈。"}}]}},"anthology":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（不同作家的作品的）选集","en":"An anthology is a collection of writings by different writers published together in one book.","ex":{"en":"...an anthology of poetry.","cn":"诗歌选集"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"poems in general, or the art of writing them","cn":""},{"en":"words arranged in the form of poetry","cn":""},{"en":"a set of poems by different people collected together in one book","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A collection of writings is an anthology. The heavy textbooks that span the literature of an entire culture and that school children transport in over-sized backpacks with wheels? Those are anthologies."}]},"collocations":{"phrases":["VERB + ANTHOLOGY compile, edit, publish, put together We have put together an anthology of children's poetry.","PREP. in an/the ~ The essay first appeared in an anthology of feminist criticism. | ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/d/anthology0205.mp3","us":"media/ldoce/hwd/ame/9/anthology.mp3"},"examples":[{"en":"an anthology of American literature","cn":"美国文学选集"}],"oxford":{"phon":"ænˈθɒlədʒi","pos":"noun","senses":[{"en":"a collection of poems, stories, etc. that have been written by different people and published together in a book","cn":"（不同作家作品的）选集","ex":{"en":"an anthology of poems for children","cn":"儿童诗选"}}]}},"ancestry":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"世系；血统","en":"Your ancestry is the fact that you are descended from certain people.","ex":{"en":"...a family who could trace their ancestry back to the sixteenth century.","cn":"世系可上溯到16世纪的家族"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you come from or are from a particular place, that is where you were born or where you lived for a long time","cn":""},{"en":"to have been born in and to have spent the early part of your life in that place -- used especially when you are writing about someone's life","cn":""},{"en":"to have been born in a particular country or to be a citizen of that country because your parents come from there, especially when you now live somewhere else","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Have a family tree hanging on the wall? Then you know a bit about your ancestry , or family history and lineage."}]},"collocations":{"phrases":["ADJ. common The two species have developed from a common ancestry. | Celtic, French, etc.","VERB + ANCESTRY claim, have, share She shares a common ancestry with the Queen. | trace We can trace our ancestry back to the 16th century.","ANCESTRY + VERB date/go/reach/stretch back to The firm claims an ancestry dating back to 1727.","PHRASES be of French, German, etc. ancestry He is of Chines e ancestry ."]},"media":{"uk":"media/ldoce/hwd/bre/6/ancestry0205.mp3","us":"media/ldoce/hwd/ame/a/ancestry.mp3"},"examples":[{"en":"He was able to trace his ancestry back over 1 000 years.","cn":"他可追祖溯宗至 1 000 年以前。"},{"en":"to have Scottish ancestry","cn":"祖籍苏格兰"}],"oxford":{"phon":"ˈænsestri","pos":"noun","senses":[{"en":"the family or the group of people that you come from","cn":"（统称）祖宗，祖先；列祖列宗","lab":"figurative","ex":{"en":"to have Scottish ancestry","cn":"祖籍苏格兰"}}]}},"anaesthetic":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"麻醉药；麻醉剂","en":"Anaesthetic is a substance that doctors use to stop you feeling pain during an operation, either in the whole of your body when you are unconscious, or in a part of your body when you are awake.","ex":{"en":"The operation is carried out under a general anaesthetic.","cn":"该手术是在全身麻醉情况下实施的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drug that stops you feeling pain","cn":"麻醉剂"}]},"collocations":{"phrases":["ADJ. general, local","VERB + ANAESTHETIC administer, give sb He was given a general anaesthetic. | use The operation was completed in ten minutes using only local","ANAESTHETIC + VERB take effect, work The anaesthetic began to take effect. | wear off","PREP. under (an/the) ~ It would have to be done under anaesthetic. | without (an/the) ~ They had to operate without anaesthetic."]},"media":{"uk":"media/ldoce/hwd/bre/d/anaesthetic0205.mp3","us":"media/ldoce/hwd/ame/2/laadanaesthetic.mp3"},"examples":[{"en":"They gave him a general anaesthetic (= one that makes you become unconscious).","cn":"他们对他施行了全身麻醉。"},{"en":"How long will I be under anaesthetic?","cn":"我会给麻醉多长时间？"}],"oxford":{"phon":"ˌænəsˈθetɪk","pos":"noun","senses":[{"en":"a drug that makes a person or an animal unable to feel anything, especially pain, either in the whole body or in a part of the body","cn":"麻醉药；麻醉剂","ex":{"en":"How long will I be under anaesthetic?","cn":"我会处于麻醉状态多长时间？"}},{"en":"containing a substance that makes a person or an animal unable to feel pain in all or part of the body","cn":"麻醉的","ex":{"en":"an anaesthetic drug/spray","cn":"麻醉药；麻醉喷剂"},"pos":"adjective"}]}},"anguish":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（精神上的）悲痛；（身体上的）剧痛","en":"Anguish is great mental suffering or physical pain.","ex":{"en":"A cry of anguish burst from her lips","cn":"她突然痛苦地大叫了一声。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling of not being happy or relaxed and thinking a lot about a problem or something that is wrong","cn":""},{"en":"the feeling of being worried because you think that something bad has happened or will happen, and you feel that you have no control over the situation","cn":""},{"en":"a worried feeling – use this especially when many people are worried about a problem that affects everyone","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"The noun anguish refers to severe physical or emotional pain or distress. A trip to the dentist might cause a cavity-prone person a lot of anguish ."}]},"collocations":{"phrases":["ADJ. bitter, deep, great, real | inner, personal, private | mental, physical, spiritual","VERB + ANGUISH cause The loss of a pet can cause some people real anguish. | experience, feel, suffer He suffered the anguish of watching hi","PREP. in (sb's) ~ to cry out/groan/scream in anguish In her anguish, she turned to her father for help. | with ~ His mouth felt dry with ang","PHRASES a cry/groan/scream of anguish, pain and anguish All the pain and anguish inside her rose like a tidal wave."]},"media":{"uk":"media/ldoce/hwd/bre/b/anguish0205.mp3","us":"media/ldoce/hwd/ame/a/anguish.mp3"},"examples":[{"en":"an anguished letter from her prison cell","cn":"她从狱中寄来的一封悲痛欲绝的信"},{"en":"Tears of anguish filled her eyes.","cn":"她双眸噙满了伤心的泪水。"}],"oxford":{"phon":"ˈæŋɡwɪʃ","pos":"noun","senses":[{"en":"severe physical or mental pain, difficulty or unhappiness","cn":"剧痛；痛苦；苦难","ex":{"en":"He groaned in anguish.","cn":"他痛苦地呻吟。"}}]}},"analyst":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"分析者；分析家","en":"An analyst is a person whose job is to analyse a subject and give opinions about it.","ex":{"en":"...a political analyst.","cn":"政治分析家"}},{"pos":"N-COUNT 可数名词","cn":"心理分析医师","en":"An analyst is someone, usually a doctor, who examines and treats people who are emotionally disturbed."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a doctor who treats people with mental illnesses, using drugs or other forms of medical treatment","cn":""},{"en":"a doctor or other trained person who treats people with mental or emotional problems, especially by talking with them about their thoughts, feelings, and past experiences","cn":""},{"en":"someone who is trained to understand people's behaviour and help them with mental or emotional problems, but who is not a medical doctor","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Analyst means someone who looks over data and comes to a conclusion regarding its meaning, as in “My stock analyst had looked at all of the market data and said that the future was bright for my investments.”"}]},"collocations":{"phrases":["ADJ. leading a leading business analyst | business, computer, data, financial, industry, investment, market, military, policy, political, re","PREP. ~ of He was a shrewd analyst of players' strengths and weaknesses. • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/b/analyst0205.mp3","us":"media/ldoce/hwd/ame/7/analyst.mp3"},"examples":[{"en":"City analysts forecast huge profits this year.","cn":"伦敦金融分析家预测今年的利润非常丰厚。"},{"en":"a political/food analyst","cn":"政治分析家；食物化验员"}],"oxford":{"phon":"ˈænəlɪst","pos":"noun","senses":[{"en":"a person whose job involves examining facts or materials in order to give an opinion on them","cn":"分析者；化验员","ex":{"en":"a political/financial analyst","cn":"政治／金融分析师"}},{"en":"a person who treats patients using psychoanalysis","cn":"精神分析师"}]}},"antique":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"古物；古玩；古董","en":"An antique is an old object such as a piece of china or furniture which is valuable because of its beauty or rarity.","ex":{"en":"...a genuine antique.","cn":"一件古董真品"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very old – used about things that existed thousands of years ago, or things that look very old","cn":""},{"en":"antique furniture, clocks, jewellery etc are old and often valuable","cn":""},{"en":"used about traditions, problems, or situations that have existed for a very long time","cn":""}]},"vocab":{"pos":"adj n v","senses":[{"en":"An antique is an old-fashioned thing, like a lamp from the sixties. Anything antique is old or at least old-ish."}]},"collocations":{"phrases":["ADJ. fine | genuine | priceless, valuable","VERB + ANTIQUE collect","ANTIQUE + NOUN dealer | antiques fair/shop"]},"media":{"img":["media/ldoce/img/antique_chair.jpg"],"uk":"media/ldoce/hwd/bre/3/antique_n0205.mp3","us":"media/ldoce/hwd/ame/f/antique1.mp3"},"examples":[{"en":"Priceless antiques were destroyed in the fire.","cn":"无价之宝的古董在大火中焚毁。"},{"en":"an antique shop (= one that sells antiques )","cn":"古玩店"}],"oxford":{"phon":"ænˈtiːk","pos":"adjective","senses":[{"en":"old and often valuable","cn":"古老的；古董的","ex":{"en":"an antique mahogany desk","cn":"古红木办公桌"}},{"en":"an object such as a piece of furniture that is old and often valuable","cn":"文物；古物；古董；古玩","ex":{"en":"Priceless antiques were destroyed in the fire.","cn":"价值连城的古董在大火中焚毁。"},"pos":"noun"}]}},"annex":{"collins":{"senses":[{"pos":"VERB 动词","cn":"并吞，占领（国家或地域）","en":"If a country annexes another country or an area of land, it seizes it and takes control of it.","ex":{"en":"Rome annexed the Nabatean kingdom in 106 AD","cn":"公元106年罗马吞并了纳巴泰王国。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take control of a country or area next to your own, especially by using force 〔","cn":"尤指通过武力〕并吞﹐兼并﹐霸占〔邻国或相邻地区〕"}]},"vocab":{"pos":"v n","senses":[{"en":"An annex is an extension of, or an addition to a building. A small room off of a main room is an annex, and attics are another type of annex."}]},"collocations":{"phrases":["ADV. formally The region was formally annexed in 1892. | illegally","PREP. to The territory had been annexed to Poland."]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeannex.mp3","us":"media/ldoce/hwd/ame/6/annex1.mp3"},"examples":[{"en":"Germany annexed Austria in 1938. * 1938","cn":"年德国吞并了奥地利。"},{"en":"Germany annexed Austria in 1938.","cn":""}],"oxford":{"phon":"ˈæneks","pos":"verb","senses":[{"en":"to take control of a country, region, etc., especially by force","cn":"强占，并吞（国家、地区等）","ex":{"en":"Germany annexed Austria in 1938.","cn":"1938 年德国吞并了奥地利。"}}]}},"antiseptic":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"杀菌剂；防腐剂；消毒剂","en":"Antiseptic is a substance that kills germs and harmful bacteria.","ex":{"en":"She bathed the cut with antiseptic.","cn":"她用消毒剂浸洗伤口。"}},{"pos":"ADJ 形容词","cn":"杀菌的；防腐的","en":"Something that is antiseptic kills germs and harmful bacteria.","ex":{"en":"These vegetables and herbs have strong antiseptic qualities.","cn":"这些蔬菜和草本植物有很强的杀菌性。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a medicine that you put onto a wound to stop it from becoming infected","cn":"抗菌剂﹐消毒剂"},{"en":"helping to prevent infection","cn":"抗菌的﹔抗感染的"}]},"vocab":{"pos":"adj n","senses":[{"en":"If you are out to kill some micro-organisms, an antiseptic will come in handy! If you go to a hospital for a cut on your arm, the nurse will apply an antiseptic to the wound because it will kill any bacteria, while not harming your healthy skin."}]},"collocations":{"phrases":["ADJ. powerful | mild Mint is a mild antiseptic.","VERB + ANTISEPTIC apply, put on You should put some antiseptic on that cut."]},"media":{"uk":"media/ldoce/hwd/bre/8/antiseptic_n0205.mp3","us":"media/ldoce/hwd/ame/d/antiseptic.mp3"},"examples":[{"en":"Cover the burn with an antiseptic dressing.","cn":"在烧伤处包上无菌敷料。"},{"en":"antiseptic cream/lotion/wipes","cn":"防腐乳膏/洗液/擦剂"}],"oxford":{"phon":"ˌæntiˈseptɪk","pos":"noun","senses":[{"en":"a substance that helps to prevent infection in wounds by killing bacteria","cn":"防腐剂；抗菌剂","ex":{"en":"a mild/strong/powerful antiseptic","cn":"温和/强效/强效防腐剂"}},{"en":"able to prevent infection","cn":"防腐的；抗菌的","ex":{"en":"antiseptic cream/lotion/wipes","cn":"防腐乳膏／洗液／擦剂"},"pos":"adjective"},{"en":"very clean and free from bacteria","cn":"无菌的；消过毒的","ex":{"en":"Cover the burn with an antiseptic dressing.","cn":"在烧伤处包上无菌敷料。"},"pos":"adjective"}]}},"antibiotic":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"抗生素；抗菌素","en":"Antibiotics are medical drugs used to kill bacteria and treat infections.","ex":{"en":"Your doctor may prescribe a course of antibiotics.","cn":"你的医生可能会开一个疗程的抗生素。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drug that is used to kill bacteria and cure infections","cn":"抗生素"}]},"vocab":{"pos":"n adj","senses":[{"en":"An antibiotic is a substance used to kill bacteria. If you're coughing up green stuff, the doctor might give you an antibiotic to fight the infection."}]},"collocations":{"phrases":["ADJ. effective","QUANT. course, dose The doctor put her on a course of antibiotics.","VERB + ANTIBIOTIC be on, take Did you remember to take your antibiotics? | give sb, prescribe, put sb on, treat sth with The doctor prescrib"]},"media":{"uk":"media/ldoce/hwd/bre/7/antibiotic0205.mp3","us":"media/ldoce/hwd/ame/5/antibiotic.mp3"},"examples":[{"en":"The doctor put her on antibiotics (= told her to take them).","cn":"医生要她服用抗生素。"},{"en":"effective antibiotic treatment","cn":"有效的抗生素治疗"}],"oxford":{"phon":"ˌæntibaɪˈɒtɪk","pos":"noun","senses":[{"en":"a substance, for example penicillin, that can destroy or prevent the growth of bacteria and cure infections","cn":"抗生素，抗菌素（如青霉素）","ex":{"en":"The doctor put her on antibiotics (= told her to take them).","cn":"医生要她服用抗生素。"}},{"en":"containing or using a substance, for example penicillin, that can destroy or prevent the growth of bacteria and cure infections","cn":"抗菌素，抗生素（如青霉素）","ex":{"en":"an antibiotic drug","cn":"抗生素"},"pos":"adjective"}]}},"antipathy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"憎恶；反感","en":"Antipathy is a strong feeling of dislike or hostility towards someone or something.","ex":{"en":"She'd often spoken of her antipathy towards London.","cn":"她常提及她对伦敦的反感。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"strong disagreement with or protest against something","cn":""},{"en":"a reason you give for opposing an idea or plan","cn":""},{"en":"a strong feeling of opposition to something, or dislike for someone, which is shown in your behaviour, and has often existed for a long time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An antipathy is a deep-seated dislike of something or someone. Usually it's a condition that is long-term, innate, and pretty unlikely to change — like your antipathy for the Red Sox."}]},"collocations":{"phrases":["ADJ. deep, profound, strong, violent | growing, increasing | mutual They have a mutual antipathy to each other. | personal Despite his perso","VERB + ANTIPATHY feel, have | express, show","PREP. ~ between There was a lot of antipathy between the two doctors. | ~ for his antipathy for his boss | ~ to/towards I feel a profound an"]},"media":{"uk":"media/ldoce/hwd/bre/9/antipathy0205.mp3","us":"media/ldoce/hwd/ame/7/antipathy.mp3"},"examples":[{"en":"a growing antipathy towards the idea","cn":"对这个想法越来越多的反感"},{"en":"personal/mutual antipathy","cn":"个人/相互反感"}],"oxford":{"phon":"ænˈtɪpəθi","pos":"noun","senses":[{"en":"a strong feeling of dislike","cn":"厌恶；反感","ex":{"en":"personal/mutual antipathy","cn":"个人／相互反感"}}]}},"ancestor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"祖宗;祖先","en":"Your ancestors are the people from whom you are descended.","ex":{"en":"...our daily lives, so different from those of our ancestors","cn":"与我们祖先的生活有着天壤之别的我们的日常生活"}},{"pos":"N-COUNT 可数名词","cn":"原种；原型","en":"An ancestor of something modern is an earlier thing from which it developed.","ex":{"en":"The direct ancestor of the modern cat was the Kaffir cat of ancient Egypt","cn":"现代猫的直系原种是古埃及的卡菲尔猫。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a member of your family, especially one who does not live with you","cn":""},{"en":"a member of your family. Relation means the same as relative . It is often used when talking about whether someone is in the same family as another person","cn":""},{"en":"someone who is a family member of a person who lived and died a long time ago, for example the great-grandchild of that person","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An ancestor came before. Your grandmother's grandmother and any relative before her is one of your ancestors ."}]},"collocations":{"phrases":["ADJ. direct The builder of the manor house is a direct ancestor of the present owner. | immediate | distant, early, remote a distant ancesto","VERB + ANCESTOR be descended from, have, share A lot of the people there are descended from a common ancestor. | trace He can trace his ance"]},"media":{"uk":"media/ldoce/hwd/bre/a/ancestor0205.mp3","us":"media/ldoce/hwd/ame/3/ancestor.mp3"},"examples":[{"en":"The ancestor of the modern bicycle was called a penny-farthing.","cn":"现代自行车的原型称作 penny-farthing（一种前轮大后轮小的自行车）。"},{"en":"a reptile that was the common ancestor of lizards and turtles","cn":"作为蜥蜴和龟的共同原种的一种爬行动物"}],"oxford":{"phon":"ˈænsestə(r)","pos":"noun","senses":[{"en":"a person in your family who lived a long time ago","cn":"祖先；祖宗","ex":{"en":"His ancestors had come to America from Ireland.","cn":"他的祖先从爱尔兰来到美国。"}},{"en":"an animal that lived in the past that a modern animal has developed from","cn":"（动物的）原始种型","ex":{"en":"a reptile that was the common ancestor of lizards and turtles","cn":"作为蜥蜴和龟的共同原种的一种爬行动物"}},{"en":"an early form of a machine that later became more developed","cn":"（机器的）原型","ex":{"en":"The ancestor of the modern bicycle was called a penny-farthing.","cn":"现代自行车的原型称作 penny-farthing（一种前轮大后轮小的自行车）。"}}]}},"anecdote":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"轶事；趣闻","en":"An anecdote is a short, amusing account of something that has happened.","ex":{"en":"Pete was telling them an anecdote about their mother","cn":"皮特正在给他们讲一件他们母亲的趣闻。"}},{"pos":"N-VAR 可变名词","cn":"（无根据的）传闻","en":"Anecdotes are individual accounts of something that are not reliable evidence.","ex":{"en":"The image of the fox as a pest is grossly exaggerated in anecdote and folklore.","cn":"狐狸的害人精形象在传闻和民间故事中遭到严重的夸大。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a description of real or imaginary events, which is told or written to entertain people","cn":""},{"en":"an exciting story about imaginary events","cn":""},{"en":"writing that describes imaginary people and events","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A short, amusing true story is an anecdote . You might come back from a crazy spring break with a lot of anecdotes to tell."}]},"collocations":{"phrases":["ADJ. amusing, entertaining, humorous | personal","VERB + ANECDOTE relate, tell She is good at telling anecdotes. | exchange, swap","PREP. ~ about We swapped anecdotes about old friends."]},"media":{"uk":"media/ldoce/hwd/bre/3/anecdote0205.mp3","us":"media/ldoce/hwd/ame/3/anecdote.mp3"},"examples":[{"en":"This research is based on anecdote, not fact.","cn":"这项研究是根据传闻，而非事实。"},{"en":"amusing anecdotes about his brief career as an actor","cn":"关于他短暂演员生涯的趣闻佚事"}],"oxford":{"phon":"ˈænɪkdəʊt","pos":"noun","senses":[{"en":"a short, interesting or funny story about a real person or event","cn":"轶事；趣闻","ex":{"en":"amusing anecdotes about his brief career as an actor","cn":"关于他短暂演员生涯的趣闻逸事"}},{"en":"a personal account of an event","cn":"传闻","ex":{"en":"This research is based on anecdote, not fact.","cn":"这项研究的根据是传闻，而非事实。"}}]}},"anonymous":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"匿名的;无名的;不知名的","en":"If you remain anonymous when you do something, you do not let people know that you were the person who did it.","ex":{"en":"You can remain anonymous if you wish","cn":"你愿意的话可以不透露姓名。"}},{"pos":"ADJ 形容词","cn":"不记名的；不具名的","en":"Something that is anonymous does not reveal who you are.","ex":{"en":"Of course, that would have to be by anonymous vote.","cn":"当然，那必须通过不记名投票的方式。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无特色的;平淡无奇的","en":"If you describe a place as anonymous, you dislike it because it has no unusual or interesting features and seems unwelcoming.","ex":{"en":"...the most anonymous part of north-west Washington","cn":"华盛顿西北部最无特色的地区"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is anonymous does something without saying what their name is, or their name is not known","cn":""},{"en":"an unnamed person is someone whose name has not been made known publicly","cn":""},{"en":"an unidentified person is someone whose name is not known because police or government officials have been unable to find out who they are, or have not said who they are","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you don't know who wrote a poem, the author is anonymous . If you don't know who donated a gift to a museum, it's called an anonymous gift from an anonymous donor. Anonymous means a person unknown."}]},"collocations":{"phrases":["VERBS be | become | remain","ADV. completely, entirely","PHRASES prefer/wish to remain anonymous My client wishes to remain anonymous."]},"media":{"uk":"media/ldoce/hwd/bre/1/anonymous0205.mp3","us":"media/ldoce/hwd/ame/6/anonymous.mp3"},"examples":[{"en":"The money was donated by a local businessman who wishes to remain anonymous.","cn":"这笔款子是当地一位不愿透露姓名的企业家捐赠的。"},{"en":"long stretches of dull and anonymous countryside","cn":"大片大片千篇一律、枯燥平淡的乡村"}],"oxford":{"phon":"əˈnɒnɪməs","pos":"adjective","senses":[{"en":"with a name that is not known or that is not made public","cn":"不知姓名的；名字不公开的","ex":{"en":"an anonymous donor","cn":"不知姓名的捐赠者"}},{"en":"written, given, made, etc. by somebody who does not want their name to be known or made public","cn":"匿名的；不具名的","ex":{"en":"an anonymous letter","cn":"匿名信"}},{"en":"without any unusual or interesting features","cn":"没有特色的","ex":{"en":"long stretches of dull and anonymous countryside","cn":"大片大片千篇一律、枯燥平淡的乡村"}}]}},"antidote":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"解毒药；解毒剂","en":"An antidote is a chemical substance that stops or controls the effect of a poison.","ex":{"en":"When he returned, he noticed their sickness and prepared an antidote.","cn":"他回来后注意到了他们的病状，于是配制了解毒剂。"}},{"pos":"N-COUNT 可数名词","cn":"矫正方法；对抗手段","en":"Something that is an antidote to a difficult or unpleasant situation helps you to overcome the situation.","ex":{"en":"Massage is a wonderful antidote to stress.","cn":"按摩是舒缓压力的一剂妙方。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a medicine or medical treatment that makes an illness go away","cn":""},{"en":"a way to treat a health problem, especially a small problem such as a cold, using plants or other natural methods","cn":""},{"en":"a medicine that will stop the effects of a poison or dangerous drug","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An antidote is a remedy that relieves. So if you get headaches from long bus rides, it's best to travel equipped with the key pain alleviating antidotes : Tylenol, lots of water and soothing music."}]},"collocations":{"phrases":["ADJ. effective | natural","VERB + ANTIDOTE administer, give The doctor administered an antidote.","PREP. ~ for Quinine is a natural antidote for this fever. | ~ to We do not have an effective antidote to this poison. 2 thing that takes awa","ADJ. effective, good, perfect, powerful","VERB + ANTIDOTE act as, serve as | offer, provide The resort offers the perfect antidote to the pressures of modern life.","PREP. ~ for I think that stricter punishment is the best antidote for crime. | ~ to Creative activity serves as an effective antidote to dep"]},"media":{"uk":"media/ldoce/hwd/bre/3/antidote0205.mp3","us":"media/ldoce/hwd/ame/7/antidote.mp3"},"examples":[{"en":"A Mediterranean cruise was the perfect antidote to a long cold winter.","cn":"到地中海航游是度过漫长寒冬的绝妙办法。"},{"en":"There is no known antidote to the poison.","cn":"这种毒的解药尚未发现。"}],"oxford":{"phon":"ˈæntidəʊt","pos":"noun","senses":[{"en":"a substance that controls the effects of a poison or disease","cn":"解毒药；解毒剂","ex":{"en":"There is no known antidote to the poison.","cn":"这种毒的解药尚未发现。"}},{"en":"anything that takes away the effects of something unpleasant","cn":"消除不快的事物；矫正方法","ex":{"en":"A Mediterranean cruise was the perfect antidote to a long cold winter.","cn":"到地中海航游是度过漫长寒冬的绝妙办法。"}}]}},"announcer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（广播电台或电视台的）广播员，播音员","en":"An announcer is someone who introduces programmes on radio or television or who reads the text of a radio or television advertisement.","ex":{"en":"The radio announcer said it was nine o'clock","cn":"电台播音员报时9点整。"}},{"pos":"N-COUNT 可数名词","cn":"（火车站、机场等的）广播员，播报员","en":"The announcer at a railway station or airport is the person who makes the announcements.","ex":{"en":"The announcer apologised for the delay.","cn":"播报员就晚点表示歉意。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone on a television or radio programme who tells you what the programme will be about, and introduces the other people in it","cn":""},{"en":"someone on a television or radio programme who tells you what the programme will be about, or who tells you about a sports game as it is happening","cn":""},{"en":"someone who introduces the people on a show and who talks to people or about reports or scenes included in the programme - use this especially about talk shows, game shows, or quiz shows","cn":""}]},"collocations":{"phrases":["ADJ. continuity, radio, sports, station, television/TV The station announcer warned us that the train was running late. • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/a/announcer0205.mp3","us":"media/ldoce/hwd/ame/2/announcer.mp3"},"oxford":{"phon":"əˈnaʊnsə(r)","pos":"noun","senses":[{"en":"a person who introduces, or gives information about, programmes on the radio or television","cn":"（广播、电视的）广播员，播音员，节目主持人","ex":{"en":"The continuity announcer advertised a few forthcoming programmes.","cn":"节目间隙播音员介绍了几个将要播出的节目。"}},{"en":"a person who gives information about something in a station, an airport, etc., especially through a loudspeaker","cn":"（车站、机场等的）广播员，播音员","ex":{"en":"The station announcer warned us that the train was running late.","cn":"车站广播员预先通知我们火车晚点了。"}},{"en":"a person who broadcasts at a sports event","cn":"（运动会上的）广播员，解说员","lab":"North American English","ex":{"en":"a play-by-play announcer (= who comments on a game as it is happening)","cn":"（体育赛事的）现场解说员"}}]}},"antarctica":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the continent which is the most southern area of land on the Earth and is mostly covered with ice.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/p028-000001612.mp3","us":"media/ldoce/hwd/ame/2/p028-000001612.mp3"},"oxford":{"phon":"ænˈtɑːktɪkə","pos":"noun","senses":[{"en":"the continent around the South Pole","cn":"南极洲（南极附近的大陆）"}]}}});
